INSERT INTO public.words (id, word, meaning, detailed_meaning, news_example, hint, related_words) VALUES
(81,'국제금융시장','국제금융시장이란 국경을 넘어 자금의 수요와 공급을 연결해 주는 시장 또는 모든 거래메커니즘을 말하며 두 가지 의미로 사용된다.','국제금융시장이란 국경을 넘어 자금의 수요와 공급을 연결해 주는 시장 또는 모든 거래메커니즘을 말하며 두 가지 의미로 사용된다. 첫째, 구체적인 장소의 개념으로 런던, 뉴욕, 도쿄 등 주요 국제금융의 중심지나 그 지역에서 운용되는 증권거래소 또는 선물옵션거래소 등을 말한다. 둘째, 추상적 개념으로 국제자금의 수요와 공급을 연결해 주는 모든 거래의 형태를 말한다. 외환시장(foreign exchange market), 단기 금융시장(money market), 중장기 금융시장(capital market), 주식시장(equity market) 및 파생금융상품시장(financial derivatives market) 등을 포괄한다.','','ㄱㅈㄱㅇㅅㅈ',ARRAY['국제금융중심지']::text[]),
(82,'국제금융중심지','특정 국가나 지역이 국제금융시장으로 기능하기 위해서는 자국 통화의 국제통용성, 상대적으로 우월한 기초경제력, 고도로 발달된 금융시장과 다양한 장단기 금융수단의 자유로 운 거래, 전 세계시장 정보의…','특정 국가나 지역이 국제금융시장으로 기능하기 위해서는 자국 통화의 국제통용성, 상대적으로 우월한 기초경제력, 고도로 발달된 금융시장과 다양한 장단기 금융수단의 자유로 운 거래, 전 세계시장 정보의 신속 저렴한 공급, 세계적인 상품 및 서비스거래의 중심지국제수지(BOP) 등의 요건을 두루 갖추어야 한다. 국제금융중심지는 이러한 국제금융시장의 요건을 갖추고 있어 세계적 금융기관들이 본점, 지점, 현지법인의 형태로 영업망을 집중시킴으로써대량의 국제금융거래가 지속적, 반복적으로 이루어지는 장소를 말한다. 대표적인 국제금 ㄱ 융중심지로는 뉴욕, 런던, 동경 등이 있다. 한편 역외 국제금융중심지는 주로 비거주자로 부터 자금을 조달하여 비거주자를 대상으로 운영되는 금융중개시장으로, 조세 및 금융규제 면에서 특혜를 부여하여 인위적으로 창설한 금융 중심지이다. 홍콩, 싱가포르, 룩셈부르크 등이 대표적이다.','','ㄱㅈㄱㅇㅈㅅㅈ',ARRAY['국제금융시장']::text[]),
(83,'국제산업연관표','국제산업연관표(International Input-Output Tables)란 국가 간 수출입을 매개로 여러나라의 산업연관표를 연결하여 하나의 산업연관표로 작성한 것이다.','국제산업연관표(International Input-Output Tables)란 국가 간 수출입을 매개로 여러나라의 산업연관표를 연결하여 하나의 산업연관표로 작성한 것이다. 국제산업연관표에 서는 한 나라 산업의 생산기술구조 및 배분구조를 국내 산업간 상호 연관관계뿐만 아니라다른 나라 산업과의 연관관계까지 포함하여 나타내고 있으므로 생산기술의 국제비교 및국가 간 상호의존관계 분석 등에 널리 이용된다. OECD에서 ICIO(Inter-Country Input-Output Table), EU에서 WIOT(World Input- Output Table), ADB에서 MRIO(Multi-Regional Input-Output Table) 등 다양한 국제산업연관표를 작성하여 글로벌 가치사슬 분석(GVC) 등에 활용하고 있으며, 한국은행에 서는 일본 아시아경제연구소(IDE; Institute of Developing Economies)와 공동으로 한 국, 일본, 중국, 미국 등 아시아·태평양권 10개국 산업연관표를 연결한 아시아 국제산업연관표를 작성한 바 있다.','','ㄱㅈㅅㅇㅇㄱㅍ',ARRAY['산업연관표(I/O Tables)']::text[]),
(84,'국제수지(BOP)','일정 기간 동안 한 나라의 거주자와 비거주자 간에 발생한 경제적 거래에 수반되는 수입과 지급의 차이를 의미한다.','일정 기간 동안 한 나라의 거주자와 비거주자 간에 발생한 경제적 거래에 수반되는 수입과 지급의 차이를 의미한다. 국제수지(BOP; Balance Of Payments)는 크게 경상수지, 자본수지, 금융계정, 오차 및 누락 등 4개의 계정으로 구성되어 있다. 경상수지는 ① 상품수출입의 결과인 상품수지, ② 운송, 여행, 건설 등 서비스거래의 결과인 서비스수지, ③ 급료 및 임금, 투자소득 등 본원소득수지, ④ 무상원조, 증여성 송금 등의 결과인 이전소득수지로 구분된다. 자본수지는 자산 소유권의 무상이전, 채권자에 의한 채무면제 등 자본이전과 브랜드네임 등 비생산·비금융자산의 취득 및 처분의 결과로 계상된다. 금융계정은 직접투자, 증권투자, 파생금융상품, 기타투자 및 준비자산으로 구분된다. 오차 및 누락은 경상수지 및 자본수지의 합계와 금융계정 금액이 같지 않을 경우 이를 조정하기 위한 항목으로 국제수지 작성에 이용되는 기초통계간 계상시점, 평가방법상의 차이 등에 기인한다.','','ㄱㅈㅅㅈ()',ARRAY['경상수지','국제수지표']::text[]),
(85,'국제수지표','일정 기간 동안 한 나라의 거주자와 비거주자 간에 발생한 경제적 거래를 국제기준에 따라 체계적으로 기록한 표이다.','일정 기간 동안 한 나라의 거주자와 비거주자 간에 발생한 경제적 거래를 국제기준에 따라 체계적으로 기록한 표이다. 이는 국제수지표가 어느 한 시점에서의 대차상황을 기록한 잔액(stock) 통계가 아니라 일정 기간 중에 발생한 거래를 집계한 플로(flow) 통계임을 의 미한다. 거주자와 비거주자의 구분은 경제주체가 어디에 살고 있으며 국적이 어디인지 하는 지리적 영역이나 법률상의 국적보다는 경제활동에 있어 주된 경제적 이익의 중심이 어디에 있느냐를 기준으로 한다. 거래유형은 모든 경제적 거래를 대상으로 하는데 상품, 서 비스, 소득, 자본 및 금융거래뿐만 아니라 대외원조 등 대가 없이 이루어지는 이전거래도 포함한다. 우리나라는 한국은행에서 국제수지표를 매월 작성하여 공표하고 있다.','','ㄱㅈㅅㅈㅍ',ARRAY['국제수지(BOP)','경상수지']::text[]),
(86,'국제원유가격','원유는 전세계적으로 수백 종이 거래되고 있다.','원유는 전세계적으로 수백 종이 거래되고 있다. 이중 국제원유시장의 대표 유종은 미국 서부텍사스유(WTI; West Texas Intermediate), 영국 브렌트유 및 아랍에미레이트 (UAE) 두바이유의 세 가지이다. WTI는 북미, 브렌트유는 유럽 및 아프리카, 두바이유는 중동을 각각 대표하는 기준유가를 정하는 유종으로 사용되고 있다. 국제원유가격은 1980 년대 중반까지는 석유수출국기구(OPEC; Organization of the Petroleum Exporting 국제통화기금(IMF) Countries)의 발표가격을 기준으로 사용하였다. 그러나 석유파동 등으로 인한 국제원유가격의 변동성을 회피하기 위해 선물거래가 활성화되면서 선물가격이 실질적인 현물유가 의 기준역할을 하게 되었다. 우리나라에서는 수입 비중이 높은 두바이유의 가격이 원유도 ㄱ 입단가에 큰 영향을 미친다. 국제석유시장에서는 선물시장 거래량이 가장 많고 광범위한 지역으로 수출되는 브렌트유의 가격이 가장 높은 대표성을 갖고 있다. 국제원유가격은 장기적으로 원유 수요와 공급에 의해 결정되나 원유 공급지의 지정학적 리스크와 기상, 미달러화 가치, 주요국 석유재고의 변동 등 많은 요인의 영향을 받는다.','','ㄱㅈㅇㅇㄱㄱ',ARRAY['선물거래']::text[]),
(87,'국제증권감독기구(IOSCO)','국제증권감독기구(IOSCO; International Organization of Securities Commissions) 는 전 세계의 증권 규제기관들이 모인 국제적인 기구로서 130여개…','국제증권감독기구(IOSCO; International Organization of Securities Commissions) 는 전 세계의 증권 규제기관들이 모인 국제적인 기구로서 130여개 국가가 회원국으로 참여하고 있다. 증권 시장의 안전성과 공정성을 보장하고, 투자자 보호를 위해 국제적인 규제 기준을 마련하는 것을 목표로 하고 있으며 전 세계 증권시장의 95% 이상이 IOSCO가 제정한 기준을 따르고 있다. IOSCO는 1983년 아메리카 대륙의 11개 증권감독기구들의 연합체로 출발하였는데, IOSCO의 ‘증권규제의 목적과 원칙’(Objectives and Principles of Securities Regulation)은 G20와 국제금융기구(IMF), 세계은행(World Bank) 등에서 도 핵심 기준으로 받아들여지고 있다. 한편 우리나라는 금융감독당국인 금융위원회와 금융감독원이 참여하고 있다.','','ㄱㅈㅈㄱㄱㄷㄱㄱ()',ARRAY['금융시장인프라(FMI)']::text[]),
(88,'국제통화기금(IMF)','국제통화 및 금융제도의 안정을 도모하기 위한 국제금융기구로서 미국 워싱턴에 본부를 두고 1945년 12월 설립되었다.','국제통화 및 금융제도의 안정을 도모하기 위한 국제금융기구로서 미국 워싱턴에 본부를 두고 1945년 12월 설립되었다. 설립목적은 국제통화문제에 관한 협력, 국제무역의 확대와 세계 경제의 균형적 성장, 외환의 안정 촉진, 다자간 결제제도 확립, 회원국의 국제수지 불균형 완화 등으로 되어 있다. 이에 따라 회원국의 환율정책 및 외환제도 관련 감시 활동, 회원국에 대한 금융지원 및 기술지원, 특별인출권(SDR)의 창출과 운영관리, 저소득국가 지원 등의 활동을 하고 있다. 회원국 가입에 특별한 제한을 두고 있지 않으며 안정적인 환율제도 운영, 경상지급에 대한 제한 철폐 등을 통해 국제통화문제에 협력할 의사가 있는 모든 나라에 대해 가입을 허용하고 있다. 가입 희망국은 총회에서의 가입결의안 채택 후 할당된 쿼타(quota)를 납입함으로써 정식 회원국이 된다. IMF(International Monetary Fund)의 재원은 회원국의 쿼타 납입금으로 조달되며 필요 한 경우 회원국으로부터 차입하고 있다. 조직은 총회와 이사회, 총회의 자문기구인 국제통화금융위원회, 총재를 비롯한 집행부서 등으로 구성되어 있다. 2025년 6월 현재 회원국 수는 191개국이며 우리나라는 1955년 8월에 가입하였다.','','ㄱㅈㅌㅎㄱㄱ()',ARRAY['IMF 쿼타','특별인출권(SDR)']::text[]),
(89,'국제통화시장(IMM)','국제통화시장(IMM; International Monetary Market)은 1972년 미국 시카고상업거래소(CME) 내에 설립된 세계 최초의 통화선물 전문거래소이다.','국제통화시장(IMM; International Monetary Market)은 1972년 미국 시카고상업거래소(CME) 내에 설립된 세계 최초의 통화선물 전문거래소이다. 환율 변동성에 대응해 기업과 투자자에게 환위험 관리 수단을 제공하기 위해 만들어졌으며, 달러, 유로, 엔, 파운드등 주요 국제통화의 선물 및 옵션 상품이 거래된다. 거래단위와 만기, 결제일 등이 표준화되어 있으며 만기는 주로 3월, 6월, 9월 및 12월의 셋째 수요일이다. IMM의 통화선물 거래는 국제 외환시장의 흐름과 투자 심리를 반영하며, 글로벌 금융시장에 중요한 신호를 제공한다. IMM 포지션(순매수·순매도 잔고 등)은 투자자들의 환율 전망과 위험회피 성향을 파악하는 데 활용되고 있다. 또한 IMM은 통화선물 거래의 표준과 글로벌 벤치마크 역할을 하며, 전 세계 주요 거래소의 통화선물 시장 도입을 유도하는 선도적 역할을 해왔다.','','ㄱㅈㅌㅎㅅㅈ()',ARRAY['시카고상업거래소']::text[]),
(90,'국제투자대조표(IIP)','국제투자대조표(IIP; International Investment Position)는 일정 시점 현재 한 나라 거주자의 비거주자에 대한 금융자산(대외투자) 및 금융부채(외국인투자) 잔액을 기록한…','국제투자대조표(IIP; International Investment Position)는 일정 시점 현재 한 나라 거주자의 비거주자에 대한 금융자산(대외투자) 및 금융부채(외국인투자) 잔액을 기록한 통계표로서 국제수지의 금융계정(직접투자, 증권투자, 파생금융상품, 기타투자, 준비자산) 과 포괄범위가 동일하다. 일정 시점의 대외금융자산/부채 잔액은 거래일 이후 환율이나 국채주가변동 등으로 인한 가치평가분이 포함되어 있기 때문에 금융계정의 거래 누계액과 차이가 있을 수 있다. 한편 국제투자대조표의 대외금융자산/부채에서 지분성투자(직접투자내 지분투자, 증권투자 내 지분증권, 기타투자 내 기타지분)와 파생금융상품을 제외할 경 ㄱ 우 대외채권·채무 통계와 개념적으로 일치한다. 국제투자대조표는 한국은행에서 매분기작성하여 발표하고 있다.','','ㄱㅈㅌㅈㄷㅈㅍ()',ARRAY['국제수지(BOP)']::text[]),
(91,'국제회계기준','국제회계기준(IFRS; International Financial Reporting Standards)은 기업의 회계처리와 재무제표에 대한 국제적 정합성을 높이기 위해서 국제회계기준위원회…','국제회계기준(IFRS; International Financial Reporting Standards)은 기업의 회계처리와 재무제표에 대한 국제적 정합성을 높이기 위해서 국제회계기준위원회(IASB; International Accounting Standards Board)가 제정한 회계처리기준을 말한다. 자본시장 개방 등 전세계의 글로벌화 진전 등으로 국제적으로 통일된 회계기준의 필요성이 증가 한 데다, 특히 2002년 발생한 엔론, 월드콤 등의 회계부정사건을 계기로 국제적으로 회계투명성에 대한 요구도 커짐에 따라 국제회계기준이 마련되었다. 국제회계기준의 핵심원칙으로는 ① 원칙중심의 기준회계 ② 연결재무제표 중심 보고 ③ 공정가치 평가 ④ 경제적실질에 기초한 회계처리 등을 들 수 있다. 회계기준 단일화 추세에 따라 전 세계 100여 개국가에서 사용 중이며 우리나라도 국내 회계 투명성에 대한 국제적 신뢰도 저하가 자본시장에 부정적인 영향을 미칠 수 있다는 우려에서 2007년 3월 「국제회계기준(IFRS) 도입로드맵」을 발표하였으며 이후 희망기업은 2009년부터, 상장회사는 2011년부터 전면 도 입되었다. 2024년 4월에는 손익의 원천을 명시하여 성과정보의 비교가능성을 높이는 방향으로 재무제표의 표시 방식을 변경하는 IFRS 18이 신규 제정되어 2027년부터 전면 적용될 예정이다.','','ㄱㅈㅎㄱㄱㅈ','{}'::text[]),
(92,'국채','국채란 정부가 다양한 목적의 재정자금을 조달하기 위해 발행하는 채권을 말한다.','국채란 정부가 다양한 목적의 재정자금을 조달하기 위해 발행하는 채권을 말한다. 국채는 자금 용도에 따라 국고채권, 재정증권, 국민주택채권 및 보상채권으로 나누어지는 데 국고채권이 국채의 대부분을 차지한다. 국고채권은 주로 국가 재정에 필요한 자금 (적자재정시 재원)을 조달하기 위해서 「국채법」에 의해 발행되는데 만기는 2년, 3년, 5년, 10년, 20년, 30년, 50년(안정적인 재정자금 조달, 국채만기 포트폴리오의 다양화를 목적으로 2016.10월에 도입) 등 7가지 종류로 구성되며 경쟁입찰방식으로 발행된다. 국고채권의 원활한 소화 및 시장조성을 위해 국채자기매매업무 취급금융기관(은행, 증권사, 종합금융회사)중 국고채권 인수 및 유통 실적이 우수한 금융기관을 국고채전문딜러(PD)로 선정·운영하고 있으며 미국의 primary dealer와 같은 기능을 수행한다. 재정증권은 재정부족자금의 일시 보전을 위해 「국고금관리법」에 의해 발행되는데 만기는 1년 이내지만 실제로는 주로 28일, 63일 등 3개월 이내이며 경쟁입찰방식으로 발행된다. 국민주택채권은 국민주택건설 재원조달을 위해 「주택도시기금법」에 의해 부동산 등기 및 인허가와 관련하여 의무적으로 매입하도록 하는 첨가소화방식으로 발행되며 만기는 5년이다. 보상채권은 공공용지 보상비 마련을 위하여 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」에 의해 당사자앞 교부방식으로 발행되며 만기는 5년 이내지만 실제로는 3년 만기로 발행한다.','','ㄱㅊ','{}'::text[]),
(93,'국채선물','국채선물이란 국가가 발행하는 채권을 기초자산으로 하는 선물거래를 의미한다.','국채선물이란 국가가 발행하는 채권을 기초자산으로 하는 선물거래를 의미한다. 국채시장규모가 확대되고 2000년 7월부터 채권시가평가제도가 시행되면서 채권 투자자에게 가격변동 위험을 관리할 수 있는 수단을 제공하면서 국채의 거래를 활성화하기 위해 1999년 9 월에 3년 만기 국채선물시장이 개설되었다. 이후 중기채권 시장 및 장기채권 시장에 대한 위험관리 수단을 제공하기 위해서 2003년 8월에 5년 만기 국채선물이 상장되었고, 2008 년 2월에는 10년 만기 국채선물이 상장되었으며, 2024년 2월에는 초장기 국채 발행량 증가에 따른 헤지 수요 및 시장의 다양한 투자 환경 구축을 위해 30년 국채선물이 상장되었다. 현재 한국거래소에는 3년, 5년, 10년, 30년 만기 국채선물이 거래되고 있다. 국채선물의 주문접수, 거래체결 및 통보과정은 전자거래방식에 의해 자동적으로 수행되고 있다. 미국 시카고상업거래소(CME; Chicago Mercantile Exchange)와 같이 특정 장소(trading pit)에서 거래 참가자들이 모여 육성 또는 수신호로 체결하는 공개호가 방식을 취하는 경우도 있으나 세계적으로 점차 전자거래 방식이 증가하는 추세를 보이고 있다.','','ㄱㅊㅅㅁ',ARRAY['채권시가평가제도','시카고상업거래소(CME)']::text[]),
(94,'규모의 경제','일반적인 경우 기업이 재화 및 서비스 생산량을 늘려감에 따라 추가적으로 소요되는 평균 ㄱ 생산비용도 점차 늘어난다.','일반적인 경우 기업이 재화 및 서비스 생산량을 늘려감에 따라 추가적으로 소요되는 평균 ㄱ 생산비용도 점차 늘어난다. 그런데 일부 재화 및 서비스 생산의 경우에는 생산량이 늘어날수록 평균비용이 감소하는 현상이 나타나는데 이를 규모의 경제(Economies of Scale) 라고 한다. 이런 현상은 초기 생산단계에서 시설투자나 연구개발 비용, 인프라 확장 등으로 막대한 투자비용이 필요하지만 생산과정의 표준화, 생산효율성 증대, 대량 생산 등으로 생산과정에서는 큰 비용이 들지 않는 반도체, 자동차, 항공기, 철강, 석유화학, 유통 및 물류 등의 산업에서 흔히 나타난다. 또한 사용자가 많을수록 가치가 높아지는 플랫폼 비즈니스나 통신망 등 네트워크 효과가 발생하는 산업에도 규모의 경제가 존재한다.','','ㄱㅁㅇㄱㅈ',ARRAY['범위의 경제']::text[]),
(95,'규제 샌드박스','규제 샌드박스(Regulatory Sandbox)는 핀테크 기업이 현행 규제를 적용받지 않으면서 자신의 혁신적인 금융상품과 비즈니스모델을 시험할 수 있는 공간이나 제도를 뜻한다.','규제 샌드박스(Regulatory Sandbox)는 핀테크 기업이 현행 규제를 적용받지 않으면서 자신의 혁신적인 금융상품과 비즈니스모델을 시험할 수 있는 공간이나 제도를 뜻한다. 이 용어는 어린이들이 안전하고 자유롭게 놀 수 있는 놀이터의 모래구역 즉 ‘sandbox’를 연상시킨다. 즉 규제 샌드박스에 참여하는 소비자에게는 안전장치를 두고, 혁신적인 기업가 에게는 규제를 면제하거나 완화함으로써, 핀테크 기업의 새로운 도전과 시험을 활성화하려는 규제기관의 정책의지 또는 참여한 기업·소비자의 혁신적인 활동모습을 연상시킨다. 이는 영국의 금융감독기구인 금융행위규제청(FCA)이 핀테크 전담조직(Innovation Hub) 을 설치하고 지속적으로 관련 산업을 지원하기 위해 규제 개선의 필요성을 검토하는 가운데 규제 개선을 위한 여러 방안들 중의 하나로 도입한 것이다. 규제 샌드박스의 장점은 ① 혁신적인 아이디어가 시장(market)에 접근할 수 있는 시간과 비용을 줄이고 ② 혁신기업의 자금조달을 쉽게 해주며 ③ 더 많은 혁신적인 상품이 시험되고 시장에 도입될 수 있을 뿐만 아니라 ④ 규제기관이 미리 새로운 상품 및 서비스에 대한 적절한 소비자보호 안전장치를 확보할 수 있다는 점이다.','','ㄱㅈㅅㄷㅂㅅ',ARRAY['핀테크','로보어드바이저']::text[]),
(96,'그램-리치-블라일리법','1999년 11월 미국 의회가 제정한 법으로서 공식 명칭은 「금융서비스현대화법(The Financial Services Modernization Act of 1999)」이다.','1999년 11월 미국 의회가 제정한 법으로서 공식 명칭은 「금융서비스현대화법(The Financial Services Modernization Act of 1999)」이다. 공화당 상원의원인 필 그램 (Phil Gramm), 공화당 하원의원인 짐 리치(Jim Leach)와 토마스 J. 블라일리(Thomas J. Bliley)가 공동으로 발의하였기 때문에 통상 「그램-리치-블라일리법(Gramm-Leach- Bliley Act)」이라 불린다. 동 법의 주된 내용은 1933년의 글래스-스티걸법 중 ‘상업은행의 증권 관련 자회사 보유 금지’와 ‘상업은행과 투자은행의 임직원 겸직 금지’ 등 핵심 조항을 폐지하는 것이다. 종전의 글래스-스티걸법 ‘조항20’에 의하면 상업은행(연준 가입은 행)은 증권의 인수와 거래를 주된 업무로 하는 자회사를 둘 수 없었으나, 그램-리치-블라일리법 제정으로 글래스-스티걸법 ‘조항20’은 전면 폐지되었다. 동 법은 금융산업의 경쟁력 강화를 명분으로 내세운 클린턴 행정부의 정책기조와 금융소비자의 편익증진 등을 구실로 삼은 월스트리트 상업은행들의 로비력이 맞물려 탄생되었다. 동 법 제정으로 미국에 서 금융자유화의 시대가 열린 가운데 대형 상업은행들이 투자은행 업무에 뛰어들면서 경쟁이 심화되었고 이로 인해 기존 투자은행 중 일부가 무리한 투자를 일삼다가 위기에 빠진 것이 글로벌 금융위기의 단초가 된 것으로 평가되고 있다.','','ㄱㄹㄹㅊㅂㄹㅇㄹㅂ',ARRAY['글래스-스티걸법','투자은행']::text[]),
(97,'그린본드','그린본드는 조달 자금을 기후 및 환경 관련 사업에 사용하는 것을 전제로 발행되는 특수목적 채권이다.','그린본드는 조달 자금을 기후 및 환경 관련 사업에 사용하는 것을 전제로 발행되는 특수목적 채권이다. 특징은 조달 자금의 사용처(use of proceeds)에 있고 발행자가 그린본드원칙(GBP; Green Bond Principle)에 따라 채권을 발행하는 경우 재량으로 이름을 지을 수 있다. 그린본드는 채권의 구조에 따라 ① 그린사업 채권 ② 그린사업 수익 채권 ③ 그린 프로젝트 채권 ④ 그린 유동화 채권으로 분류된다. 그린본드는 2007년 최초 발행(6억유로)된 이후 초기에는 주로 EIB, World Bank 등 국제기구가 글로벌 환경보호, 균형성장등과 관련해 발행을 주도하였으나 최근에는 정부기관, 기업 및 금융기관 등으로 발행기관의 범위가 확대되어 가파른 성장세를 시현하고 있다. 그린본드의 발행자는 자본비용, 기업홍보, 사업추진 용이성 측면에서 편익을 누릴 수 있다. 그린본드는 사회적 책임 투자 기회를 제공하는 한편 여타 채권과 발행방식 및 구조가 동일하여 기존 채권 포트폴리오에 근원인플레이션율쉽게 융화가 가능한 장점이 있다. 국제자본시장협회(ICMA)가 그린본드 원칙(GBP)의 운영 및 관리를 담당하고 있다.','','ㄱㄹㅂㄷ','{}'::text[]),
(98,'그림자금융/비은행금융중개(NBFI)','집합투자기구(MMF·채권형·혼합형 펀드 등), RP 거래, 유동화기구 등과 같이 은행시스템밖에서 신용중개기능을 수행하지만 은행 수준의 건전성 규제와 예금자보호가 적용되지않는 기관 또는 활동을…','집합투자기구(MMF·채권형·혼합형 펀드 등), RP 거래, 유동화기구 등과 같이 은행시스템밖에서 신용중개기능을 수행하지만 은행 수준의 건전성 규제와 예금자보호가 적용되지않는 기관 또는 활동을 이르는 용어이다. 그림자금융(Shadow Banking)은 은행의 전통적인 자금중개기능을 보완하는 한편 금융업의 경쟁을 촉진함으로써 효율적인 신용 배분에 기여하는 순기능을 발휘한다. 그러나 글로벌 금융위기 과정에서 느슨한 규제 하에 과도한 리스크 및 레버리지 축적, 은행시스템과의 직·간접적 연계성 등을 통해 시스템 리스크를 촉발·확산시킨 원인 중 하나로 지목되기도 하였다. 이에 따라 금융안정위원회(FSB), 바젤은행감독위원회(BCBS) 등 국제금융감독기준 제정기구를 중심으로 그림자금융에 대한 모니터링 체계 구축 및 규제개혁 논의가 진행되어왔다. 한편 FSB는 그림자금융의 순기능 등 을 고려하여 2018년 10월부터 “그림자금융(Shadow Banking)”이라는 용어를 보다 중립적인 의미가 담긴 “비은행금융중개(Non-Bank Financial Intermediation)”로 변경하여사용하고 있다.','','ㄱㄹㅈㄱㅇ/ㅂㅇㅎㄱㅇㅈㄱ()','{}'::text[]),
(99,'근원인플레이션율','근원인플레이션율(Core Inflation Rate)은 물가변동을 초래하는 여러 요인들 가운데 일시적인 공급충격의 영향을 제외한 기조적인 물가상승률을 말한다.','근원인플레이션율(Core Inflation Rate)은 물가변동을 초래하는 여러 요인들 가운데 일시적인 공급충격의 영향을 제외한 기조적인 물가상승률을 말한다. 일반적으로 전체 소비자물가 상승률에서 농산물가격, 국제원자재가격 등의 변동 부분을 제거하여 계산한다. 우리나라는 근원인플레이션 지표로 농산물 및 석유류제외지수를 작성해 왔으며, 2010년 기준 지수부터 OECD 방식에 의한 식료품 및 에너지제외지수를 추가로 작성하고 있다. 근원인플레이션율은 물가에 미치는 단기적 충격이나 불규칙 요인이 제외되어 기조적인 물가상승의 흐름을 포착할 수 있다는 장점을 갖고 있는 반면 일반 국민이 실제 느끼는 체감물가와 괴리될 가능성을 내포하고 있다.','','ㄱㅇㅇㅍㄹㅇㅅㅇ',ARRAY['기대인플레이션','인플레이션']::text[]),
(100,'글래스-스티걸법','미국 의회가 제정한 법으로 공식 명칭은 「1933년 은행법(Banking Act of 1933)」이다.','미국 의회가 제정한 법으로 공식 명칭은 「1933년 은행법(Banking Act of 1933)」이다. 민주당 상원의원 카터 글래스(Carter Glass)와 민주당 하원의원 헨리 B. 스티걸(Henry B. Steagall)이 공동으로 제안하였기 때문에 통상 「글래스-스티걸법(Glass-Steagall Act)」이라불린다. 은행들의 고객 자산을 이용한 방만한 투자행위가 1929년의 주가폭락과 그에 이은 금융위기 및 대공황의 원인 중 하나로 지목됨에 따라 ‘은행개혁’과 ‘투기규제’를 목적으로 동 법이 제정되었다. 동 법의 핵심 내용은 기존 은행을 상업은행과 투자은행으로 구분하고 이들의 업무를 엄격하게 분리하려는 것이다. 이에 따라 상업은행은 증권의 발행 및 인수가 금지되고 증권 관련 자회사 보유도 금지되었으며, 투자은행은 일반인으로부터 예금을 받을 수 없고, 상업은행과 투자은행간에 임직원의 겸직이 금지되었다. 또한 동 법을 통해 연방예금보험공사(FDIC; Federal Deposit Insurance Corp.)를 설립하여 연방예금보험제도를 도입하고 금융에 대한 연방준비제도의 통제를 강화하였으며 연방공개시장위원회(FOMC)를 설치하였다. 동 법 시행 이후 미국에서는 상업은행과 투자은행의 영역이 엄격히 분리되어 골드만삭스·모건스탠리·메릴린치 등은 투자은행으로, JP모건·뱅크오브아메리카·시티뱅크 등은 대형 상업은행으로 성장하였다. 동 법에 대해서는 경쟁을 제한하여 금융산업의 비효율성을 초래하였다는 부정적 평가와 수십 년에 걸친 미국 금융시스템의 안정에 기여하였다는 긍정적 평가가 공존하고 있다. 1999년 11월 금융산업 경쟁력 강화를 명분으로 내세운 클린턴 행정부의 정책기조와 월스트리트 상업은행들의 로비력이 맞물리면서 ‘상업은행의 증권 관련 자회사 보유’ 및 ‘상업은행과 투자은행의 임직원 겸직’ 허용을 주요 내용으로 하는 그램-리치-블라일리법(Gramm-Leach-Bliley Act)이 제정됨으로써 글래스-스티걸법의 핵심 조항은 폐지되었다.','','ㄱㄹㅅㅅㅌㄱㅂ',ARRAY['리쇼어링/니어쇼어링/프렌드쇼어링']::text[]),
(101,'글로벌 공급망 압력 지수','글로벌 공급망 압력지수(GSCPI; Global Supply Chain Pressure Index)는 국제 교역이 이루어지는 과정에서 공급망이 얼마나 원활히 작동하는지 보여주는 지표이다.','글로벌 공급망 압력지수(GSCPI; Global Supply Chain Pressure Index)는 국제 교역이 이루어지는 과정에서 공급망이 얼마나 원활히 작동하는지 보여주는 지표이다. 미국 뉴욕연방준비은행(Federal Reserve Bank of New York)이 세계 각국의 무역, 물류, 운송 관련데이터를 분석하여 매달 발표하고 있다. GSCPI 수치가 0에 가까울수록 공급망이 정상적이고 안정적인 반면 0보다 크면 공급망에 압력이 높아서 차질이 심한 상태를 의미하는데코로나19 팬데믹과 우크라이나 전쟁 때 역사적으로 높은 수준을 기록한 바 있다. GSCPI 는 경제정책 결정자들에게 공급망 리스크 판단 지표 중 하나로 인플레이션 예측과 글로벌경기 흐름 파악에 유용하며, 기업의 생산 및 재고 전략 수립에도 활용된다.','','ㄱㄹㅂㄱㄱㅁㅇㄹㅈㅅ',ARRAY['인플레이션','경기']::text[]),
(102,'글로벌 금융위기','글로벌 금융위기는 전 세계 금융시스템에 심각한 혼란을 일으키는 위기 상황을 의미한다.','글로벌 금융위기는 전 세계 금융시스템에 심각한 혼란을 일으키는 위기 상황을 의미한다. 특히 2008년 미국에서 시작된 글로벌 금융위기는 전 세계적인 경기침체를 초래하였으며 국제금융시장 전반에 걸쳐 큰 충격을 주었다. 이러한 위기는 특정 국가의 경제 문제에서 시작되어 전 세계로 빠르게 확산되는 특징을 보인다. 2008년 글로벌 금융위기의 주된 원인은 미국 서브프라임 모기지 부실에서 비롯되었다. 위기 이전에 발생한 금융기관의 과도 한 대출과 부실 채권이 주택가격 하락과 맞물리면서 주택저당증권(MBS)의 가치 하락을 초래했고, 이는 다시 금융시스템 전체의 위기로 확산되었다. 이에 더해 금융 감독 및 규제 체계의 미흡, 과도한 신용팽창 등이 복합적으로 작용하여 위기를 더욱 심화시켰다. 이 과정에서 은행시스템에 대한 신뢰가 상실되어 주요 금융기관들이 파산하고 정부의 개입이 필요하게 되었다. 실물경제 측면에서는 여러 나라에서 심각한 경제 위축과 큰 폭의 실업률 증가를 야기했으며, 이에 대한 대응으로 중앙은행의 금리 인하 및 양적 완화, 정부의 재정 확대 정책 등이 시행되었다. 이 위기를 통해 얻은 교훈을 바탕으로 금융시스템의 안정성을 높이고, 경제 위기 발생 시 효과적으로 대응할 수 있는 시스템을 구축하는 것이 중요하다는 인식이 제고되었다.','','ㄱㄹㅂㄱㅇㅇㄱ',ARRAY['주택저당채권(MBS)','양적 완화']::text[]),
(103,'글로벌금융안전망','금융위기 등으로 인하여 외화유동성이 부족해지는 경우에 대비하기 위하여 각국이 외화유동성을 인출하거나 지원받는 각종 제도적 장치들을 총칭하여 글로벌금융안전망이라고 한다.','금융위기 등으로 인하여 외화유동성이 부족해지는 경우에 대비하기 위하여 각국이 외화유동성을 인출하거나 지원받는 각종 제도적 장치들을 총칭하여 글로벌금융안전망이라고 한다. 글로벌금융안전망은 위기 시 유동성을 지원할 수 있는 국제금융기구의 재원이 제한 적인 점을 감안하여 위기의 성격·규모에 따라 보다 효과적으로 대응하기 위해 중층적으로 구축할 필요가 있다. 이러한 중층적 금융안전망은 일반적으로 외환보유액과 같은 개별국가 차원의 금융안전망, 중앙은행들의 양자간 통화스왑, CMIM과 같은 특정 지역 내 다자간 금융협정을 포괄하는 지역 차원의 금융안전망, IMF와 같은 범세계적 통화금융기구의 자금지원제도를 포괄하는 글로벌 차원의 금융안전망 등으로 구성된다. 전통적으로 각국정부는 금융위기 등에 대비한 기본적인 금융안전망으로 외환보유액을 중시해왔다. 그러나 2008년 글로벌금융위기 대응과정에서 중앙은행 간 통화스왑 등 양자간 협력의 중요성이 크게 부각되었으며, 인접국 간의 경제적 협력을 통해 거시경제 및 금융의 안정을 도모하는 다자간 금융협정도 발전하고 있다. 이 밖에 IMF의 대출제도 확충 등 범세계적인 국제금융기구의 자금지원 제도도 더욱 확충되면서 글로벌 금융안전망의 중심적 역할을 담당하고 있다.','','ㄱㄹㅂㄱㅇㅇㅈㅁ',ARRAY['외환보유액','지역금융협정','치앙마이 이니셔티브(CMI)']::text[]),
(104,'금리선물','금리선물(Interest Rate Futures)이란 기초자산인 금리를 거래대상으로 하며 현재의 시 ㄱ 점에서 정한 가격으로 미래의 특정 시점에서 사거나 팔 것을 약정하는 계약을 말하다.','금리선물(Interest Rate Futures)이란 기초자산인 금리를 거래대상으로 하며 현재의 시 ㄱ 점에서 정한 가격으로 미래의 특정 시점에서 사거나 팔 것을 약정하는 계약을 말하다. 금리선물의 대표적인 상품은 기초자산별로 다양한 만기의 국채선물이다. 3년 국채선물의 주요 내용을 보면 다음과 같다. 기초자산은 최종결제일 현재 만기 3년, 액면금액 1억원, 표면금리 5%, 반기별로 이자를 지급하는 가상의 국고채권이다. 가격의 표시방법은 액면금액 1억원을 100으로 환산하여 소수점 둘째자리까지 표시한다. 최소가격 변동폭인 1tick의 크기는 0.01인데 그 가치는 가상채권 가격으로는 10,000원에 해당되며 국고채금리 1bp(0.01%)는 국채선물가격 3tick과 거의 동일하다. 투자자들은 금리변동위험 헤지(hedge) 및 투기적 목적으로 국채선물을 거래한다. 일반적으로 은행, 보험사 등 기관투자가들은 현물채권을 다량으로 보유하고 있으므로 향후 시장금리가 상승하면 채권가격이 하락하는 금리위험에 노출되어 있다. 이런 위험을 회피하기 위해 국채선물을 매도(시장금리 상승에 따른 보유채권의 가격 하락이 국채선물 매도에 따른 이익으로 상쇄)하게되는데 이를 헤지거래라고 한다. 반면 보유채권 없이 국채선물가격의 방향을 예측하고 이 를 바탕으로 국채선물을 매수 또는 매도하여 이익을 추구하는 거래를 할 수 있는데 이를 투기적 거래라고 한다. 국채선물의 경우 거래증거금률이 매우 낮아(3년 만기, 0.5%) 레버리지가 매우 높으므로 헤지펀드 등 외국인들이 이런 투기적 거래를 많이 이용하고 있으며 국채선물가격에 미치는 영향도 상당히 크다. 한편 금리선물시장에서의 가격 움직임을 보고 향후 시장금리가 어떤 방향으로 움직일 것인지를 예측하기도 하는데 특히 미국의 페더럴펀드금리선물(federal funds futures)은 시장참가자들에게 향후 미연준이 통화정책을 어떤 방향으로 운용할 것인지를 가늠해 볼 수 있는 지표역할을 하기도 한다.','','ㄱㄹㅅㅁ','{}'::text[]),
(105,'금리스왑','금리스왑(IRS; Interest Rate Swaps)이란 금리변동위험 헤지 및 차입비용 절감 등을 위하여 거래당사자간에 원금교환 없이 정기적으로 통상 3개월마다 변동금리(91일물 CD금리) 와…','금리스왑(IRS; Interest Rate Swaps)이란 금리변동위험 헤지 및 차입비용 절감 등을 위하여 거래당사자간에 원금교환 없이 정기적으로 통상 3개월마다 변동금리(91일물 CD금리) 와 고정금리(IRS금리)를 교환하는 거래를 말한다. 이때 고정금리를 지급하는 대신 변동금리를 수취하는 거래를 금리스왑 pay거래라 하며 반대로 고정금리를 수취하는 대신 변동금리를 지급하는 거래를 금리스왑 receive거래라 한다. 거래단위와 만기는 제한이 없지만 통상 100억원, 만기 1~5년 거래가 주를 이룬다. 일반적으로 금리스왑은 고정금리부 자산과 고정금리부 부채의 듀레이션이 불일치함에 따라 발생하는 금리변동위험을 헤지하는데이용된다. 예를 들어 고정금리부 자산이 고정금리부 부채보다 많은 경우 고정금리부 부채를 늘릴 필요가 있는데 이때 금리스왑거래를 통해 채권매도와 같은 효과를 내는 금리스왑 pay거래를 실시하면 금리변동위험이 감소한다. 금리스왑도 향후 금리변동에 따른 위험을 회피하기 위한 헤지거래와 향후 금리 방향을 예상하여 이익을 추구하는 투기적 거래가 있다. 앞서 제시한 예시는 헤지거래에 해당한다. 자신의 자산·부채 포지션과 관계없이 금리하락을 예상하여 수익을 추구하는 경우에는 금리스왑 receive거래를, 금리 상승을 예상하여 수익을 추구하는 경우에는 금리스왑 pay거래를 하게 되는데 전형적인 투기적 거래에 해당한다. 금리스왑시장에서는 금리스왑 스프레드라는 용어가 자주 등장한다. 이는 동일만기 「IRS금리-국고채금리(무위험채권)」를 의미한다. 금리스왑 스프레드는 향후 금리전망, 거래상대방의 신용위험 등 다양한 요인에 의해 변동된다. 예를 들어 스왑딜러가 향후시장금리가 하락할 것으로 예상하여 변동금리를 지급하는 대신 고정금리를 수취하는 금리스왑 receive거래를 하는 경우 고정금리 수취 수요가 증가함에 따라 IRS금리가 하락하면서 금리스왑 스프레드는 축소된다.','','ㄱㄹㅅㅇ','{}'::text[]),
(106,'금리자유화','금리자유화란 금리규제를 철폐함으로써 금리가 시장의 자금수급에 따라 자유로이 결정될수 있도록 하는 조치이다.','금리자유화란 금리규제를 철폐함으로써 금리가 시장의 자금수급에 따라 자유로이 결정될수 있도록 하는 조치이다. 금융시장의 대표적인 가격변수인 금리를 제한하는 것은 역사적으로 보아 미국 등 다수의 국가에서 금융불안이 반복적으로 발생함에 따라 금융안정을 도 모하기 위해 도입한 금융규제의 하나이다. 이러한 구조적 금융규제로는 금리규제 이외에 업무영역규제, 진입제한 등이 있다. 그러나 1970~80년대 인플레이션이 심화되면서 은행의 자금중개가 위축되는 이른바 디스인터미디에이션(disintermediation)이 발생하는 가 운데 금융규제를 우회하는 금융혁신이 진전되고 금융자유화가 추진되면서 각국은 금리규제를 단계적으로 철폐하였다. 대표적으로 미국의 경우 ‘레귤레이션 큐(Q)’라는 연준 규정에 의해 은행예금 최고금리가 제한되었는데, 1980년대 일련의 자유화조치 등으로 금리자유화가 진전되었다. 한국은 금융기관 간 경쟁을 촉진함으로써 금융의 효율성을 높이고 금융산업의 대외경쟁력을 강화하기 위하여 1991년 8월 수립된 “4단계 금리자유화 추진계획”에 따라 1995년 11월 제3단계 금리자유화를 완결하였다. 이어 2004년 2월부터는 금본위제요구불예금 금리도 자유화함에 따라 모든 예금의 금리상한 규제가 폐지되었다. 우리나라의 경우 금융부문 낙후의 주요 원인이 금리의 가격기능 위축에 있다는 점에서 금리자유화는 시장원리에 의한 경제운용과 통화정책의 유효성 제고를 위한 기반이 되었다. ㄱ','','ㄱㄹㅈㅇㅎ','{}'::text[]),
(107,'금리평가이론','완전한 금융시장에서, 즉 국경 간 자본이동에 규제가 없고 거래비용이나 세금 등을 고려하지 않은 경우, 양국 간의 금리 차는 선물환 프리미엄(또는 스왑레이트)과 같다는 이론이 다.','완전한 금융시장에서, 즉 국경 간 자본이동에 규제가 없고 거래비용이나 세금 등을 고려하지 않은 경우, 양국 간의 금리 차는 선물환 프리미엄(또는 스왑레이트)과 같다는 이론이 다. 예를 들어 1억 원을 가진 우리나라의 투자자가 1년간 미국 또는 우리나라의 채권에 투자할 경우 완전한 금융시장에서는 1년 후 투자자가 받는 원리금은 한국에 투자한 것이든미국에 투자한 것이든 같아야 한다. 이는 아래 식과 같이 표시할 수 있다. ￦1억 ￦1억 × (1+ i) = ( ) × (1+ i*) × F S 단, i: 한국 1년물 채권금리, i* : 미국 1년물 채권금리, S : 현물환율, F : 1년 만기 선물환율위 식은 다음과 같이 정리할 수 있다. F-S S ≒ i-i * 즉, 완전한 금융시장에서 양국 간 금리 차는 현물환율(S)과 선물환율(F) 간 차이를 현물환율로 나눈 것(이를 스왑레이트라 한다.)과 같아야 한다. 다만 현실적으로는 거래비용 등이 있기 때문에 양자가 반드시 일치하지는 않는데, 양자간의 차이(내외 금리차-스왑레이트)가 커질 경우 환위험 없이 이익을 얻을 수있는 차익거래가 발생한다. 이에 따라 금융시장이 안정적일 경우 양자간 차이는 일정 범위 내에서 유지된다.','','ㄱㄹㅍㄱㅇㄹ',ARRAY['스왑레이트']::text[]),
(108,'금본위제','금본위제란 각국의 통화가치를 순금의 일정한 중량으로 정해 놓고 금화의 자유로운 주조와 수출입을 허용하며 이를 지폐나 예금통화 등과 교환할 수 있도록 하는 제도이다.','금본위제란 각국의 통화가치를 순금의 일정한 중량으로 정해 놓고 금화의 자유로운 주조와 수출입을 허용하며 이를 지폐나 예금통화 등과 교환할 수 있도록 하는 제도이다. 금본위제하에서 각국 통화는 금의 중량을 기준으로 그 가치가 정해져 있으므로 통화 간 교환비율은 금을 통하여 고정되며, 따라서 금본위제는 전형적인 고정환율제도이다. 1800년대영국의 금본위제 도입을 시작으로 독일, 네덜란드, 노르웨이, 스웨덴, 덴마크, 프랑스, 일본 등 주요 국가들이 금본위제를 채택하였다. 금본위제는 금의 국제수지 및 국내물가 자동 조절기능을 통해 국제금융 및 세계 경제의 발전에 공헌하였으나 1차 세계대전 이후 주요국들이 과다한 전비지출로 말미암은 인플레이션과 정치적 불안 등의 문제에 직면하면서 이들 국가를 중심으로 제도의 유용성에 대한 의문이 높아졌다. 특히 전후 영국이 과대평가된 파운드화로 인한 막대한 실업과 수출산업의 침체를 겪고, 이어서 독일의 초인플레이 션, 세계 대공황 등이 발생함에 따라 영국은 1931년 금본위제를 포기하고 파운드화의 평가절하를 단행하였다. 이후 주요 선진국들도 금본위제를 포기하고 변동환율제도로 전환하면서 금본위제는 결국 붕괴하였다.','','ㄱㅂㅇㅈ',ARRAY['고정환율제도/자유변동환율제도']::text[]),
(109,'금산분리','산업자본과 금융자본이 결합하는 것을 제한하는 원칙을 금산분리라고 한다.','산업자본과 금융자본이 결합하는 것을 제한하는 원칙을 금산분리라고 한다. 은행업 등 금융산업은 예금이나 채권 등을 통하여 조달된 자금을 재원으로 하여 영업활동을 해서 자기자본비율이 낮은 특징이 있다. 이 때문에 금융산업의 소유구조는 다른 산업에 비해 취약한 편이며 산업자본의 지배하에 놓일 수 있는 위험이 존재한다. 산업자본이 금융자본을 지배하게 되면, 은행이 특정 기업의 사금고처럼 이용될 수 있는 한편, 지배기업이 다른 경쟁 기업보다 유리한 조건으로 자금을 조달할 수 있어 시장의 공정한 경쟁을 저해하고 독과점을 초래할 수 있다. 이러한 이유로 은행법을 통해 산업자본이 보유할 수 있는 은행지분을 원칙적으로 4% 한도로 제한하고 있다. 금융EDI EDI(Electronic Data Interchange)는 기업 상호 간에 접속된 컴퓨터를 이용하여 재화와 용역의 거래정보를 표준화된 양식으로 교환하여 상거래를 처리함으로써 각종 서류작성 및 거래 정보의 컴퓨터 중복입력 등을 생략하고 업무처리의 정확성 및 효율성을 높이 기 위해 개발된 시스템이다. 표준화된 형태의 정보이므로 수신한 기업이나 조직에서는 새로이 입력할 필요 없이 전송받은 그대로 업무에 활용할 수 있어서 작성상의 오류를 방지금융불안지수(FSI) 하고 업무처리 시간을 크게 단축함은 물론 인력 및 재고량의 감축, 대고객 서비스 향상 등 을 기할 수 있다. EDI 표준은 용도에 따라 전자문서표준, 메시지표준, 통신표준 등으로 구분된다. 한편 이와 같은 상거래 과정에 은행이 개입하여 기업의 거래정보뿐만 아니라 기 ㄱ 업과 거래은행 간의 지급결제를 포함한 거래정보까지도 전자적으로 처리함으로써 모든거래를 신속히 종결시키는 시스템을 금융EDI라고 한다.','','ㄱㅅㅂㄹ',ARRAY['전자금융']::text[]),
(110,'금융 하부구조','지급결제시스템, 신용평가제도, 주식시장, 선물시장 등과 같이 금융거래가 원활하게 이루어질 수 있도록 지원하는 각종 제도적 장치 및 기관을 의미한다.','지급결제시스템, 신용평가제도, 주식시장, 선물시장 등과 같이 금융거래가 원활하게 이루어질 수 있도록 지원하는 각종 제도적 장치 및 기관을 의미한다. 이는 도로, 항만시설 등 과 같이 실물경제에서 생산에 직접 기여하지는 않으나 생산활동에 없어서는 안 되는 사회간접자본에 비유할 수 있다. 금융 하부구조(Financial Infrastructure)가 잘 갖춰지면 금융거래가 투명해지고 금융기관이 각종 위험을 회피할 수 있을 뿐만 아니라 금융 중개비용을 절감할 수 있게 됨으로써 금융의 효율성이 증진되는 효과가 있다.','','ㄱㅇㅎㅂㄱㅈ','{}'::text[]),
(111,'금융공황','금융공황(Banking Panic)은 일부 금융기관이 실물경제 침체 등으로 인한 대출 부실화로 심각한 경영난에 빠졌을 때 예금인출사태(bank run)가 해당 금융기관만이 아닌 다른 금융기관에까지…','금융공황(Banking Panic)은 일부 금융기관이 실물경제 침체 등으로 인한 대출 부실화로 심각한 경영난에 빠졌을 때 예금인출사태(bank run)가 해당 금융기관만이 아닌 다른 금융기관에까지 급속하게 확산되어 금융시장 전체가 신용경색 사태에 직면하는 현상을 말한다. 이때 금융기관의 자산가치가 급격히 하락하면서 경기침체도 가속화된다. 금융공황은 증시 폭락, 금융자산 버블 붕괴, 통화위기, 국가부도 등을 동반하기도 한다. 예를 들어, 1907년 미국에서 발생한 금융공황을 보면, 뉴욕증권거래소 주가가 전년도 최고치에 비해 절반 수준까지 폭락하면서 다수의 은행에서 예금인출사태가 일어났다. 뉴욕에서 시작된 위기가 곧 미국 전역에 확산되면서 많은 은행과 기업이 파산하고 실업자 수는 400만명에 달하였다. 예금인출사태가 발생한 것은 뉴욕의 금융기관에 유동성이 부족했던 데다 예금자의 불신이 커졌던 데 기인한다. 당시 중앙은행이 존재하지 않았던 미국은 금융공황을 극복하기 위하여 1913년 12월 윌슨 대통령의 중앙은행 설립 관련 법안 서명을 거쳐 연방준비제도(Federal Reserve System)를 설립하였다.','','ㄱㅇㄱㅎ',ARRAY['뱅크런','연방준비제도(FRS)/연방준비은행(FRB)']::text[]),
(112,'금융불안지수(FSI)','금융불안지수(FSI; Financial Stress Index)는 금융불안 가능성을 속보성 있게 판단하는 지수이다.','금융불안지수(FSI; Financial Stress Index)는 금융불안 가능성을 속보성 있게 판단하는 지수이다. 상당수의 국가에서 동 지수를 편제하여 금융시스템 안정성에 대한 조기경보 판단지표로 활용하고 있다. 우리나라의 경우 한국은행이 2012년 최초 편제한 이후 현재까지 매월 산출하고 있다. 한국은행에서 편제하고 있는 금융불안지수(FSI)는 금융시장, 실물, 대외, 은행, 비은행 등 총 5개 부문으로 구성되어 있다. 세부지표로는 코스피 변동성(금융시장), 소비자심리지수(실물), 원달러환율 변동성(대외), 연체율(은행 및 비은행) 등 총 20개가 있다. 금융불안지수는 0~100의 수치로 나타내며 주의 및 위험 수준 단계의 임계치는 각각 12와 24이다. 즉 동 지수가 12를 넘으면 금융안정상황이 주의 수준 단계에, 24를 넘으면 위험 수준 단계에 진입하였음을 의미한다.','','ㄱㅇㅂㅇㅈㅅ()',ARRAY['금융취약성지수(FVI)']::text[]),
(113,'금융사이클','경제주체의 위험추구 성향, 신용담보로 제공되는 실물자산의 가치변동 등이 상호작용하면서 나타나는 금융변수들의 종합적인 순환변동을 의미한다.','경제주체의 위험추구 성향, 신용담보로 제공되는 실물자산의 가치변동 등이 상호작용하면서 나타나는 금융변수들의 종합적인 순환변동을 의미한다. 금융사이클 측정에는 BIS(국제결제은행)에서 제시하고 있는 실질 민간신용총량, 민간신용/명목GDP 비율, 비핵심부채(예금은행 총부채 - 원화예수금) 비중 등이 활용되고 있다. 한국은행에서 1980 년부터 2021년까지 분기단위 민간신용총액을 이용하여 금융사이클을 측정한 결과, 금융사이클의 평균주기는 24.5분기로 실물사이클(14.5분기)에 비해 더 긴 것으로 분석되었다. 금융사이클과 실물사이클간 동조화 관계는 2000년 들어 크게 강화되었으나, 2008년글로벌 금융위기 이후에는 동조화 관계가 약화된 것으로 나타났다.','','ㄱㅇㅅㅇㅋ','{}'::text[]),
(114,'금융상황지수(FCI)','금융상황지수(FCI; Financial Conditions Index)는 전반적인 금융여건의 완화 또는 긴축 여부를 판단하기 위한 지수이다.','금융상황지수(FCI; Financial Conditions Index)는 전반적인 금융여건의 완화 또는 긴축 여부를 판단하기 위한 지수이다. 금융상황은 통화정책의 1차 파급경로로서 실물경제전반에 영향을 미치는 만큼 주요국 중앙은행들은 금리, 환율, 주가, 신용스프레드, 주택가 격 등 다양한 금융변수를 이용하여 지수를 산출하고 이를 통화정책 운영에 참고하고 있다. 예를 들어, 장단기 시장금리가 낮아지고 주가가 상승하는 경우 금융상황이 완화된 것으로 해석된다. 반대로 금리 상승, 주가 하락 등이 나타나면 금융상황이 긴축된 것으로 본다. 한국은행은 단기금리, 실효환율, 주가, 기간스프레드, 리스크프리미엄, 주택가격의 6 개 변수의 장기추세 대비 격차를 가중합산한 후 표준화하여 FCI 지수를 산출해 왔으며, 2025년 3월부터는 금융여건이 일정 시차를 두고 성장에 영향을 미치는 점을 고려하여금융시장인프라현재의 금융상황을 판단할 수 있도록 고안된 FCI-G(1년, 3년)를 신규로 산출하여 금융상황 평가에 활용하고 있다.','','ㄱㅇㅅㅎㅈㅅ()','{}'::text[]),
(115,'금융시스템 상호연계성','금융불안을 초래할 수 있는 시스템 리스크는 시계열 차원뿐만 아니라 특정 시점에서 종합적으로 파악할 필요가 있는데, 특정 시점에서 시스템 리스크를 초래할 수 있는 핵심 요인인 상호연계성은 해당…','금융불안을 초래할 수 있는 시스템 리스크는 시계열 차원뿐만 아니라 특정 시점에서 종합적으로 파악할 필요가 있는데, 특정 시점에서 시스템 리스크를 초래할 수 있는 핵심 요인인 상호연계성은 해당 금융업권(기관)이 영업활동 과정에서 여타 금융업권(기관)과 밀접하게 연결된 정도를 의미한다. 금융시스템 상호연계 구조는 금융기관 간 자금의 조달 및운용을 통한 실제 상호거래 또는 금융기관의 주가, 금리 등 금융시장 가격변수의 상관관계 등을 이용하여 분석한다.','','ㄱㅇㅅㅅㅌㅅㅎㅇㄱㅅ',ARRAY['시스템 리스크']::text[]),
(116,'금융시장인프라','금융시장인프라(FMI; Financial Market Infrastructure)는 금융 거래지급, 청산, 결제, 기록 등을 가능하게 하는 시스템과 기관들을 총칭하는 용어이다.','금융시장인프라(FMI; Financial Market Infrastructure)는 금융 거래지급, 청산, 결제, 기록 등을 가능하게 하는 시스템과 기관들을 총칭하는 용어이다. FMI의 주요 구성요소는 지급시스템(Payment Systems), 증권결제시스템(Securities Settlement Systems), 중앙예탁기관(CSD; Central Securities Depository), 중앙청산소(CCP; Central Counterparty)로 구분할 수 있다. FMI는 금융시장의 안정성을 유지하고 효율성을 증진시키는 데 필수적인 역할을 수행한다. FMI에 문제가 발생하면 광범위한 금융 혼란을 초래할 수 있으므로, 각국 중앙은행과 금융당국은 FMI의 안전성과 효율성을 철저히 관리하고 있다. 특히, 2008년 글로벌 금융위기 이후 FMI의 중요성이 더욱 부각되어 국제적으로 ‘금융시장인프라에 관한 원칙(PFMI; Principles for Financial Market Infrastructures)’이 제정되어 안전성 및 효율성 강화 노력이 이루어지고 있다.','','ㄱㅇㅅㅈㅇㅍㄹ',ARRAY['지급결제시스템','증권결제시스템']::text[]),
(117,'금융안정','금융회사들이 정상적인 자금중개기능을 수행하고, 금융시장 참가자들의 신뢰가 유지되는 가운데 금융인프라가 잘 구비되어 있어 금융시스템이 원활히 작동하는 상태를 의미한다.','금융회사들이 정상적인 자금중개기능을 수행하고, 금융시장 참가자들의 신뢰가 유지되는 가운데 금융인프라가 잘 구비되어 있어 금융시스템이 원활히 작동하는 상태를 의미한다. 금융안정은 지속가능한 경제발전을 위해 물가안정이나 경제성장과 함께 반드시 달성되어야 하는 정책목표의 하나로서, 각국 정책당국은 이를 이루기 위해 정책적 노력을 경주하고 있다. 금융안정의 개념이 본격적으로 관심의 대상이 된 것은 1980년대 이후이다. 금융자유화, 국제화 등 세계적인 금융혁신의 확대와 금리·주가·환율의 변동성 증대, 금융기관간 경쟁 심화 등으로 특정 금융기관 및 금융시장의 불안이 전체 금융시스템의 불안으로 확산될 수 있는 위험성이 높아지게 되면서 금융안정의 중요성이 부각되었다. 1990년대초 북유럽 3국의 금융불안, 1994년 멕시코, 1997년 아시아의 금융위기, 1998년 러시아의 모라토리엄 선언 등 국제적인 금융시스템 불안 사례가 연이어 발생하고 이러한 불안이 다른 국가로 확산되는 국제적 전염효과까지 나타나면서 금융안정은 정책당국의 주요 관심사가 되었다. 2007년 미국의 서브프라임 모기지 사태와 2008년 9월 리먼브라더스 파산으로 촉발된 글로벌 금융위기는 세계적인 금융불안과 실물경제 침체라는 전례가 드문충격을 가져오면서 각국 정책당국과 시장참가자에게 금융안정의 중요성과 정책수단의 개발 필요성을 재인식하는 계기가 되었다. 2011년 9월 「한국은행법」 개정으로 한국은행은 금융안정 책무를 명시적으로 부여받았다.','','ㄱㅇㅇㅈ',ARRAY['시스템 리스크']::text[]),
(118,'금융안정위원회(FSB)','기존 금융안정포럼(FSF)의 국제금융시장 안정 기능을 보다 강화하기 위하여 동 포럼의 참여 대상, 책무, 권한 등을 확대·개편하여 2009년 4월 금융안정위원회(FSB; Financial…','기존 금융안정포럼(FSF)의 국제금융시장 안정 기능을 보다 강화하기 위하여 동 포럼의 참여 대상, 책무, 권한 등을 확대·개편하여 2009년 4월 금융안정위원회(FSB; Financial Stability Board)가 설립되었다. 현재 25개국의 금융당국(중앙은행, 재무부 및 감독기관)과 10개 국제기구 대표가 회원으로 활동하고 있으며 우리나라에서는 한국은행과 금융위원회가 참여하고 있다. 최고의사결정기구는 총회(Plenary)로서 통상 1년에 두 번 개최되며, 총회를 효과적으로 보좌할 수 있도록 산하에 운영위원회를 설치·운영하고 있다. 아울러 FSB의 책무 수행을 지원하기 위하여 취약성평가 상임위(SCAV), 감독·규제협력금융의 탈중개화상임위(SRC), 기준이행 상임위(SCSI), 예산·재원 상임위(SCBR) 등 4개의 상임위원회를 두고 있다.','','ㄱㅇㅇㅈㅇㅇㅎ()','{}'::text[]),
(119,'금융연관비율(골드스미스비율)','금융연관비율(Financial Interrelations Ratio)은 한 나라의 금융자산 잔액을 유형자산 (실물자산 또는 국부 = 유형자산 + 순 대외자산) 잔액으로 나눈 비율로 골드스미스…','금융연관비율(Financial Interrelations Ratio)은 한 나라의 금융자산 잔액을 유형자산 (실물자산 또는 국부 = 유형자산 + 순 대외자산) 잔액으로 나눈 비율로 골드스미스 (R.W.Goldsmith)가 사용하기 시작하였다. 이는 실물 면의 자본축적 잔액에 대한 금융 면의 금융자산 잔액의 비율로서 유형고정자산의 증대를 위한 금융조직의 발달 정도, 즉 금융구조의 고도화 또는 금융자산축적의 정도를 나타내는 지표라 할 수 있다. 그러나 한 나 라의 유형자산 규모를 파악하는 것이 쉽지 않아 유형자산 대신 명목 GNI를 이용하기도 한다. 일반적으로 금융연관비율은 경제의 발전에 따라 증대되는 경향이 있다.','','ㄱㅇㅇㄱㅂㅇ(ㄱㄷㅅㅁㅅㅂㅇ)','{}'::text[]),
(120,'금융의 증권화','금융의 증권화(Securitization)란 금융기관이 보유하고 있는 대출채권(loan claim) 등 유동성이 낮은 자산을 매매 가능한 유가증권 형태로 전환하는 자산유동화를 지칭한다.','금융의 증권화(Securitization)란 금융기관이 보유하고 있는 대출채권(loan claim) 등 유동성이 낮은 자산을 매매 가능한 유가증권 형태로 전환하는 자산유동화를 지칭한다. 자산유동화(ABS; Asset-Backed Securities)는 기초자산을 자산보유자로부터 분리·집합 (pooling)하여 현금흐름 등을 조정하는 구조화 과정과 신용보강을 거쳐 유동화 증권을 발행·매각하는 형태로 이루어진다. 자산유동화증권은 법적 성격 및 기초자산의 종류에 따라다양한 명칭이 붙는데, 모기지대출을 기초자산으로 유동화한 증권을 주택저당증권(MBS), 대출채권을 기초자산으로 유동화한 증권을 CLO(Collateralized Loan Obligation), 회사채를 기초자산으로 유동화한 증권을 CBO(Collateralized Bond Obligation), 자동차 할부금융을 기초자산으로 유동화한 증권을 auto loan ABS라고 부른다.','','ㄱㅇㅇㅈㄱㅎ','{}'::text[]),
(121,'금융의 탈중개화','분산원장 등 신기술의 출현과 핀테크의 발달에 따라 금융업의 분화 현상이 심화됨으로써금융서비스가 더 이상 기존 금융시스템과 중개기관에 의존하지 않고 다양한 형태로 분절되는 탈중개화…','분산원장 등 신기술의 출현과 핀테크의 발달에 따라 금융업의 분화 현상이 심화됨으로써금융서비스가 더 이상 기존 금융시스템과 중개기관에 의존하지 않고 다양한 형태로 분절되는 탈중개화(disintermediation) 및 탈집중화(decentralization)되는 경향이 나타나고 있다. 여기서 금융의 탈중개화는 블록체인을 통한 송금, P2P대출처럼 금융중개기관을 거치지 않고 거래가 당사자 간에 직접 이뤄지는 현상을 말한다. 이는 금융중개기관에 대한 수요를 감소시키는 반면, 금융서비스 공급자의 수를 증가시키는 방향으로 작용한다.','','ㄱㅇㅇㅌㅈㄱㅎ',ARRAY['핀테크','금융의 탈집중화','블록체인','P2P대출']::text[]),
(122,'금융의 탈집중화','금융의 탈집중화(Decentralization)는 탈중개화와 유사한 개념으로 분야별 금융시장에 새로 진입한 핀테크 업체들의 파괴적인 경쟁력 때문에 금융 분야별로 서비스가 더 세분화되는…','금융의 탈집중화(Decentralization)는 탈중개화와 유사한 개념으로 분야별 금융시장에 새로 진입한 핀테크 업체들의 파괴적인 경쟁력 때문에 금융 분야별로 서비스가 더 세분화되는(unbundling) 현상을 말한다. 예를 들면, 대출 분야의 경우 지점을 갖지 않는 인터넷전문은행이 인터넷(모바일) 금융서비스 분야에 새로 진입하여 획기적으로 단기간에 대규모 고객을 확보함에 따라, 기존 대형 은행들의 고객 이탈을 초래하고, 해외송금 분야에서는 블록체인·모바일네트워크 등을 활용해서 금융중개기관을 거치지 않고 더 싼 수수료로 직접 수신자에게 송금하는 핀테크 업체가 등장하였다. ‘금융의 탈중개화’(disintermediation)는 블록체인을 통한 송금, P2P대출처럼 금융중개를 거치지 않고 거래가 당사자 간에 직접 이뤄진다는 면에서 탈중개화와 다소 다르다.','','ㄱㅇㅇㅌㅈㅈㅎ',ARRAY['핀테크','P2P대출','블록체인']::text[]),
(123,'금융이해력','금융이해력은 재무적 자원을 효과적으로 관리하고 생애 전반에 걸쳐 재정적 안정을 확보하기 위해 필요한 금융 지식, 기술, 태도 등을 포괄하는 능력을 의미한다.','금융이해력은 재무적 자원을 효과적으로 관리하고 생애 전반에 걸쳐 재정적 안정을 확보하기 위해 필요한 금융 지식, 기술, 태도 등을 포괄하는 능력을 의미한다. 이는 금융 정보를 이해하고 활용하여 합리적인 금융 결정을 내리고, 자신의 재무 목표를 달성하는 데 필요한 역량을 말한다. 일반적으로 금융이해력은 금융지식, 금융행위, 금융태도와 같은 요 소들을 포괄한다. 금융 지식은 금융 상품, 시장, 서비스 등에 대한 기본적인 이해력을 말한다. 금융 행위는 예산 관리, 저축, 투자, 신용 관리 등 실제 금융 활동을 효과적으로 수행하는 능력을 말한다. 금융 태도는 미래를 위한 계획, 위험 감수, 소비 습관 등 금융 의사결정에 영향을 미치는 태도를 의미한다. 이러한 금융이해력은 개인의 재정적 안정뿐만 아니라 사회 전체의 경제적 복지에도 영향을 미치기 때문에 금융교육을 통해 금융이해력을 금융중개지원대출제도 높이는 것이 매우 중요하다. 이와 관련해 한국은행과 금융감독원은 2012년부터 OECD INFE(International Network on Financial Education) 가이드 라인을 바탕으로 한 ‘전국민 금융이해력 조사’를 공동 실시하고 있다. ㄱ','','ㄱㅇㅇㅎㄹ',ARRAY['금융 지식','금융 행위','금융 태도','디지털 금융이해력']::text[]),
(124,'금융제도','금융거래에 관한 체계와 규범을 총칭하는 개념으로 금융시장, 금융기관, 금융하부구조 (infra-structure)로 구분된다.','금융거래에 관한 체계와 규범을 총칭하는 개념으로 금융시장, 금융기관, 금융하부구조 (infra-structure)로 구분된다. 금융시장은 자금의 수요자와 공급자 간에 금융거래가 조직적으로 이루어지는 장소로서 정보시스템 등 추상적 공간을 포함하는 개념이다. 금융시장은 은행 등 금융중개기관을 통하여 예금, 대출 등의 형태로 자금 이전이 이루어지는 간접금융시장과 주식, 채권 등 증권을 통해 자금의 수요자와 공급자 간에 직접적인 자금 이 전이 이루어지는 직접금융시장으로 구분된다. 금융기관은 자금의 공급자와 수요자 간에 거래를 성립시켜 주는 것을 목적으로 하는 사업체로서 우리나라의 경우 은행, 비은행 예금취급기관, 금융투자업자, 보험회사 및 기타 금융기관으로 구분된다. 금융하부구조는 금융기관의 인가 및 경영, 재산권 보호 등을 규정하는 법령과 금융시장의 거래준칙, 금융거래 및 금융기관 업무를 지원하고 감시하는 각종 기구를 포함한다. 금융하부구조를 이루는 주요 기구로는 중앙은행, 지급결제기구, 금융감독기구, 예금보험기구 등이 있다.','','ㄱㅇㅈㄷ','{}'::text[]),
(125,'금융중개지원대출제도','한국은행의 금융중개지원대출제도는 은행의 중소기업에 대한 대출 확대를 유도하기 위해 은행별 중소기업 대출 취급실적에 비례하여 한국은행이 낮은 금리로 자금을 공급하는 대출제도를 말한다.','한국은행의 금융중개지원대출제도는 은행의 중소기업에 대한 대출 확대를 유도하기 위해 은행별 중소기업 대출 취급실적에 비례하여 한국은행이 낮은 금리로 자금을 공급하는 대출제도를 말한다. 한국은행이 사전에 설정한 지원대상 대출의 요건에 따라 은행이 개별기업을 심사한 후 자체자금으로 지원대상 대출을 취급하면, 한국은행이 사후적으로 은행별 취급실적에 따라 자금을 지원한다. 금융중개지원대출의 금리는 통상 한국은행 기준금리보다 낮게 운용되고, 대출기간은 1개월이며 월중 취급실적 변동을 반영하기 위해 월단위로 갱신한다. 금융중개지원대출은 금융통화위원회가 정한 한도 이내에서 세부 지원목적에 따라 다음의 프로그램으로 구분·운용되고 있다. 무역금융지원 프로그램은 수출금융지원을 위해 무역금융 취급실적 등에 대해 지원한다. 신성장·일자리지원 프로그램은 창업 7년 이내, 혹은 일자리 창출에 기여하는 기업을 지원한다. 지방중소기업지원 프로그램은 지역간 균형발전을 도모할 목적으로 은행의 지방중소기업에 대한 대출을 지원하며, 지역별 경제사정 등을 감안하여 한국은행 지역본부별로 운영한다. 마지막으로, 한도유보분은 자연재해 등 예기치 못한 경제충격으로 자금사정에 어려움을 겪는 중소기업을 지원하기 위한 한시적 프로그램으로 현재 중소기업 한시 특별지원, 재해복구특별지원 프로그램으로 세분화하여 운영하고 있다.','','ㄱㅇㅈㄱㅈㅇㄷㅊㅈㄷ','{}'::text[]),
(126,'금융지주회사','금융지주회사(Financial Holding Company)는 지분 보유를 통해 은행, 증권, 보험, 자산관리 등의 금융업을 영위하는 자회사들을 소유하여 경영하는 모회사를 말한다.','금융지주회사(Financial Holding Company)는 지분 보유를 통해 은행, 증권, 보험, 자산관리 등의 금융업을 영위하는 자회사들을 소유하여 경영하는 모회사를 말한다. 미국의 경우 여러 금융자회사의 지분을 보유한 일종의 페이퍼 컴퍼니(paper company)로서 금융지주회사를 설립하는 형태인데 비해서 유럽의 경우 유니버셜 뱅킹을 주축으로 하는 모은행이 바로 지주회사가 되어 여타 금융업을 하는 별도 법인의 금융회사를 자회사로 보유하는 형태가 보통이다. 금융지주회사 제도는 금융의 대형화 및 겸업화를 통해 금융산업의 경쟁력을 높일 수 있는 장점이 있으나 대형 금융기관의 시장지배력 증대와 은행과 증권업의 분리 등 금융안정을 위한 방화벽(fire wall)의 약화가 단점으로 지적된다. 우리나라에 서는 자본시장의 발달과 금융의 대형화 추세, 금융기관의 업무영역 확대 노력 등을 반영하여 2000년 10월 금융지주회사법이 제정되었다. 금융지주회사법에 의하면 금융지주회사는 주식 또는 지분의 소유를 통하여 하나 이상의 금융기관을 지배하는 것을 주된 사업으로 영위하는 회사로 여기에서 주된 사업이라 함은 금융지주회사가 보유하는 자회사 주식총액이 금융지주회사 자산의 50% 이상인 경우를 말한다.','','ㄱㅇㅈㅈㅎㅅ','{}'::text[]),
(127,'금융채','금융채는 은행, 금융투자회사, 리스회사, 신용카드회사 등 금융기관이 장기적으로 안정적인 자금을 조달하기 위하여 발행하는 채권을 말한다.','금융채는 은행, 금융투자회사, 리스회사, 신용카드회사 등 금융기관이 장기적으로 안정적인 자금을 조달하기 위하여 발행하는 채권을 말한다. 예를 들면, 은행채는 「은행법」에 근거하여 은행이 자기자본의 5배 이내에서 발행할 수 있으며, 산업금융채권의 경우 「한국산업은행법」에 근거하여 한국산업은행이 자본금 및 적립금의 30배 이내에서 발행할 수금융통화위원회있다. 중소기업금융채권은 기업은행이 「중소기업은행법」에 근거하여 자본금 및 적립금의 20배 이내에서 발행할 수 있다. 금융채는 채권의 성격에 따라 일반채권, 후순위채권, 하이 브리드채권(신종자본증권), 기타 주식관련 사채, 옵션부채권 등으로 구분된다. 금융기관 ㄱ 은 금융채를 발행하여 조달한 자금을 주로 장기 산업자금으로 대출한다. 한편 금융채 금리는 은행의 대출금리와도 관련이 있다. 금융채 금리는 단독으로 은행 대출금리의 준거금리가 되기도 하고 자금조달비용지수(COFIX; Cost of Funds Index) 산정시 예금금리, CD금리 등과 함께 가중평균되어 반영되기도 한다.','','ㄱㅇㅊ',ARRAY['자금조달비용지수(COFIX)']::text[]),
(128,'금융취약성지수(FVI)','금융안정 상황을 판단하기 위해 금융시스템 내 잠재하고 있는 취약성(vulnerability)을 평가하고 이를 통해 중장기 금융안정 리스크를 측정하는 금융안정 관련 지수이다.','금융안정 상황을 판단하기 위해 금융시스템 내 잠재하고 있는 취약성(vulnerability)을 평가하고 이를 통해 중장기 금융안정 리스크를 측정하는 금융안정 관련 지수이다. 금융취약성지수(FVI; Financial Vulnerability Index)는 구체적으로 자산가격의 과도한 상승, 신용축적 심화 등으로 인한 금융 불균형과 대내외 충격을 흡수할 수 있는 금융기관의 복원력(resilience)을 함께 고려함으로써 금융안정과 관련한 전반적인 취약성을 평가하는 데중점을 두고 있다. 이는 금융시장 가격변수 변동, 경제주체 심리 변화 등 금융·경제 상황의 단기적 변동에 중점을 두고 있는 금융불안지수(FSI)를 보완하는 성격의 지수라고 볼 수있다. 한국은행은 주요국 중앙은행 및 국제기구와 더불어 2021년 6월부터 금융취약성지수를 편제해오고 있으며, 금융취약성지수의 추이는 과거 위기 전후 우리나라의 금융취약성 수준을 비교적 정확히 설명하는 것으로 나타났다.','','ㄱㅇㅊㅇㅅㅈㅅ()',ARRAY['금융불안지수(FSI)']::text[]),
(129,'금융통화위원회','금융통화위원회(Monetary Policy Board)는 통화신용정책 수립 및 한국은행 운영에 관한 최고 의사결정기구로서 7명의 위원으로 구성된다.','금융통화위원회(Monetary Policy Board)는 통화신용정책 수립 및 한국은행 운영에 관한 최고 의사결정기구로서 7명의 위원으로 구성된다. 한국은행 총재와 부총재는 금융통화위원회의 당연직 위원이 되고, 총재는 의장을 겸임한다. 총재는 국무회의 심의와 국회 인사청문을 거쳐 대통령이 임명하고, 부총재는 총재의 추천으로 대통령이 임명한다. 임명직 위원들은 각 추천기관(기획재정부, 한국은행, 금융위원회, 대한상공회의소, 전국은행연합회)의 추천을 받아 대통령이 임명한다. 원칙적으로 매월 둘째, 넷째 목요일에 정기회의를 개최하고 필요한 경우 수시로 임시회의를 개최한다. 통화정책방향(기준금리 포함) 의결을 위한 정기회의는 종전의 매년 12회(매월)에서 2017년부터 매년 8회(1, 2, 4, 5, 7, 8, 10, 11월)로 변경되었다.','','ㄱㅇㅌㅎㅇㅇㅎ',ARRAY['한국은행']::text[]),
(130,'금전신탁','금전신탁이란 수탁자가 금전을 신탁재산으로 위탁받아 이를 대출, 채권 등 적절한 투자대상에 운용하여 얻은 이익을 수익자에게 금전 등의 형태로 되돌려 주는 제도이다.','금전신탁이란 수탁자가 금전을 신탁재산으로 위탁받아 이를 대출, 채권 등 적절한 투자대상에 운용하여 얻은 이익을 수익자에게 금전 등의 형태로 되돌려 주는 제도이다. 신탁은 재산(금전, 부동산 등)을 잘 운용하기 어려운 사람들을 위해 전문가에게 재산을 맡겨 잘운용하여 경제적 이득을 얻는 데 그 의의가 있다. 금전신탁은 수익자가 신탁재산의 운용을 지정하느냐 여부에 따라 특정금전신탁(지정)과 불특정금전신탁(비지정)으로 구분되며, 불특정금전신탁에는 단위 금전신탁, 추가 금전신탁, 가계 금전신탁, 기업 금전신탁 등이 있다. 한편, 은행에서 취급하고 있는 금전신탁과 예금과의 차이점을 살펴보면 운용방법에 서는 금전신탁은 신탁법 및 신탁계약에서 정해진 것에 국한된 반면 예금은 은행법 등에서 정한 범위 내에서 자유롭게 운용할 수 있다. 이익분배에 있어서는 금전신탁은 실적배당, 예금은 확정이율을 원칙으로 한다. 기대인플레이션','','ㄱㅈㅅㅌ','{}'::text[]),
(131,'기념화폐','기념화폐는 국가적 행사, 역사적 사건, 중요한 인물 또는 국가유산 등을 기념하기 위해 특 ㄱ 별히 발행되는 화폐로서 유통 목적으로 발행되는 통용 화폐와 달리, 주로 수집 가치와 기념적 의미를…','기념화폐는 국가적 행사, 역사적 사건, 중요한 인물 또는 국가유산 등을 기념하기 위해 특 ㄱ 별히 발행되는 화폐로서 유통 목적으로 발행되는 통용 화폐와 달리, 주로 수집 가치와 기념적 의미를 지니며 액면가보다 높은 가격에 판매되는 경우가 많다. 우리나라에서는 기념화폐가 주화로 발행되는 경우 ‘기념주화’, 지폐로 발행되는 경우 ‘기념은행권’이라 한다. 한국은행은 1971년 우리나라 최초의 기념주화인 ‘대한민국 반만년역사’를 시작으로, 서울올림픽대회, 정부수립 50주년, 서울 G20 정상회의 개최 등 국가적행사와 전통민속놀이, 한국의 문화유산, 한국의 국립공원 등 다양한 주제를 담은 기념주화를 발행해 왔다. 한편, 기념은행권은 평창동계올림픽 개최 기념으로 최초의 액면 2000 원 기념은행권이 발행된 바 있다.','','ㄱㄴㅎㅍ',ARRAY['화폐 발행','화폐의 액면체계']::text[]),
(132,'기대인플레이션','기대인플레이션은 향후 물가상승률에 대한 경제주체의 주관적인 전망을 나타내는 개념으로 물가안정을 추구하는 중앙은행이 관심을 기울이고 안정적으로 관리해야 하는 핵심지표 중 하나이다.','기대인플레이션은 향후 물가상승률에 대한 경제주체의 주관적인 전망을 나타내는 개념으로 물가안정을 추구하는 중앙은행이 관심을 기울이고 안정적으로 관리해야 하는 핵심지표 중 하나이다. 기대인플레이션은 임금협상, 가격설정, 투자결정 등 경제주체의 의사결정에 반영되면서 최종적으로 실제 인플레이션에 영향을 미친다. 구체적인 경로를 살펴보면 기대인플레이션 상승 시 가계는 구매력 하락을 우려하여 명목임금 상승을 요구하게 되며, 이는 상품의 생산비용 증가로 이어진다. 또한 기업은 재화 및 서비스의 가격을 올리더라도 수요가 유지될 것으로 예상하면서 실제로 가격 인상을 추진하게 된다. 또한 기대인플레이션 상승은 실질금리를 하락시켜 부동산, 주식 등의 자산에 대한 투자를 증가시킨다. 마지막으로 인플레이션 상승이 예상되는 경우 소비를 앞당기고자 하는 유인이 커져가수요가 증가하면서 실제 물가가 상승하게 된다. 따라서 중앙은행이 기대인플레이션을 안정적으로 관리하는 것은 물가안정을 위해 필수적이라고 할 수 있다.','','ㄱㄷㅇㅍㄹㅇㅅ',ARRAY['인플레이션']::text[]),
(133,'기본자본(Tier 1)','국제결제은행(BIS)의 기준에 따른 은행의 자기자본(=기본자본+보완자본)을 구성하는 요 소로서, 예상외 손실(unexpected loss)이 발생할 경우 은행이 영업을 계속하면서 손실을 흡수할 수…','국제결제은행(BIS)의 기준에 따른 은행의 자기자본(=기본자본+보완자본)을 구성하는 요 소로서, 예상외 손실(unexpected loss)이 발생할 경우 은행이 영업을 계속하면서 손실을 흡수할 수 있는 자본(going-concern capital)을 의미하며, 보통주자본(CET1; Common Equity Tier 1)과 기타기본자본(AT1; Additional Tier 1)으로 구성된다. 2008년 금융위기를 계기로 실질적인 손실흡수능력이 강조되면서 바젤Ⅲ 규제에서는 보통주자본이 기본자본의 지배적인 비중을 차지하도록 하였으며 기타기본자본의 요건 및 공제항목의 적용을 강화하였다. 바젤 Ⅲ에서는 기본자본비율이 위험가중자산의 6.0% 이상이 되도록 규정하고 있다.','','ㄱㅂㅈㅂ()',ARRAY['BIS 자기자본비율','보통주자본','기타기본자본','보완자본(Tier 2)']::text[]),
(134,'기업간(B2B) 지급시스템','기업간(B2B) 지급시스템은 전자외상매출채권(전자채권)의 발행과 만기시 결제를 처리하는 시스템으로 2002년 3월 가동되었다.','기업간(B2B) 지급시스템은 전자외상매출채권(전자채권)의 발행과 만기시 결제를 처리하는 시스템으로 2002년 3월 가동되었다. B2B 지급시스템으로 이용할 수 있는 서비스는 기업간 상거래로 발생한 채무를 기반으로 구매기업이 거래은행(발행은행)을 통하여 전자채권을 발행하고, 전자채권의 만기일에 판매기업이 거래은행(전자채권 보관은행)으로부터 구매기업이 결제한 전자채권대금을 회수하는 서비스이다. 채권의 만기일은 발행일로 부터 3영업일 이후부터 180일 이내이다. B2B 지급시스템의 이용 가능시간은 기본적으로 영업일 08시부터 22시까지이며, 전자채권 발행 및 취급과 관련한 수수료는 각 은행이 자율적으로 정한다. 기업·개인간(B2C) 지급결제시스템기업·개인간(B2C) 지급결제시스템은 인터넷쇼핑몰 등의 전자상거래에서 이루어지는 판매자 및 구매자간의 소액결제에 이용되는 지급결제시스템을 통칭하는 용어이다. B2C 결제는 전자지급결제대행서비스(PG서비스)를 통하여 이루어지는 것이 일반적인데, PG서 비스는 인터넷쇼핑몰 등의 전자상거래에서 구매자로부터 대금을 수취하여 가맹점(판매자)에게 최종적으로 지급될 수 있도록 결제에 필요한 정보를 중계하고 그 대가의 정산을 기업공개대행하거나 매개하는 서비스를 말한다. PG서비스는 사용되는 지급수단을 기준으로 크게신용카드 PG, 계좌이체 PG, 통신과금서비스(유·무선전화결제)로 구분되며, 이 외에도 다 양한 PG서비스가 있다. PG서비스는 온라인상의 결제에 사용되므로 원칙적으로 연중무 ㄱ 휴 24시간 이용할 수 있다.','','ㄱㅇㄱ()ㅈㄱㅅㅅㅌ',ARRAY['소액지급시스템','기업간(B2B) 지급시스템']::text[]),
(135,'기업경기실사지수(BSI)','한 나라의 전체 경기는 기업과 소비자들이 개별적으로 느끼는 경기를 종합한 것이라고 할수 있다.','한 나라의 전체 경기는 기업과 소비자들이 개별적으로 느끼는 경기를 종합한 것이라고 할수 있다. 이에 따라 전반적인 경기상황을 판단하는데 도움을 얻고자 기업가 및 소비자들을 대상으로 경제에 대한 인식을 조사하고 있는데 이 중 기업가를 대상으로 하는 것이 기업경기실사지수(BSI; Business Survey Index)이다. 기업경기실사지수는 국내외 경기동향에 대한 기업가들의 판단, 예측, 계획의 변화 추이를 조사하여 작성되며, 경기분석 및전망에 활용되고 있다. 한국은행의 기업경기실사지수는 OECD의 ‘기업경기조사 통일기준’에 의거 긍정, 보통, 부정 등의 3점 척도를 사용하고 있으며, 긍정적인 응답(증가 또는 호전) 비중과 부정적인 응답(감소 또는 악화) 비중의 차이로 산출된다. 이와 같이 산출된 BSI는 0에서 200의 값을 가지는데 100을 넘어서면 긍정적으로 응답한 업체 수가 부정적으로 응답한 업체 수보다 많음을 나타낸다. 즉 경기를 좋게 보고 있는 업체 수가 상대적으로 많음을 의미한다. BSI = [(긍정적 응답업체 수 - 부정적 응답업체 수)/전체 응답업체 수] × 100 + 100','','ㄱㅇㄱㄱㅅㅅㅈㅅ()',ARRAY['경제심리지수','소비자동향지수(CSI)']::text[]),
(136,'기업공개','기업공개(IPO; Initial Public Offering)란 넓은 의미로는 기업의 전반적 경영내용을 공개하는 것을 의미하며 좁은 의미로는 주식을 다수의 투자자들에게 분산 매각하는 것을 말한다.','기업공개(IPO; Initial Public Offering)란 넓은 의미로는 기업의 전반적 경영내용을 공개하는 것을 의미하며 좁은 의미로는 주식을 다수의 투자자들에게 분산 매각하는 것을 말한다. 즉 주식회사가 신규 발행 주식을 다수의 투자자로부터 모집하거나 이미 개인이나 소수 주주에게 발행되어 소유구조가 폐쇄적인 기업이 일반에 주식을 분산 매출하고 증권거래소에 상장하여 거래되도록 하는 것을 말한다. 기업공개는 주주의 분산투자 촉진 및소유분산, 자금조달능력의 향상, 주식가치의 공정한 결정, 세제상 혜택 등의 장점을 가지고 있다. 공개절차를 간단히 살펴보면 기업공개를 추진하는 기업은 먼저 금융위원회에 등 록하고 증권선물위원회가 지정하는 감사인에게 최근 사업연도 재무제표에 대한 회계감사를 받아야 한다. 그리고 대표주관회사를 선정하고 수권주식수, 1주의 액면가액 등과 관련한 정관개정 및 우리사주조합 결성 등의 절차를 진행한다. 이후 금융위원회에 증권신고서 제출, 청약·배정·주금납입, 자본금 변경 등기, 금융위원회에 증권 발행실적 보고서 제출등의 절차를 거쳐 한국거래소에 상장신청을 마치면 공개절차가 마무리된다.','','ㄱㅇㄱㄱ',ARRAY['모집']::text[]),
(137,'기업분할(물적분할, 인적분할)','기업분할이란 회사의 특정사업부를 분할하여 새로운 회사를 설립하는 것을 의미한다.','기업분할이란 회사의 특정사업부를 분할하여 새로운 회사를 설립하는 것을 의미한다. 기업분할은 특정사업부분의 전문화, 기업가치 제고, 특정사업부문 매각을 통한 재무상태 개선 등을 목적으로 한다. 기업분할은 크게 물적분할과 인적분할의 두 가지 형태로 나뉘어진다. 인적분할은 존속회사의 주주들이 자신이 보유한 지분 비율에 따라 신설법인의 주식을 비례적으로 나누어 갖는 방식이다. 인적분할의 경우 신설회사는 기존회사에서 완전하게 분리되어 경영의 독립성 확보가 가능하게 된다. 한편 물적분할은 신설된 법인의 주식을 모회사가 전부 소유하는 방식으로서 분할하는 것을 말한다. 물적분할의 경우 모회사의 신용도를 이용한 원활한 자금조달, 자회사 매각을 통한 용이한 투자금 회수 등의 장점이 있으나 기존 주주들은 신설회사의 주식을 직접 소유하지 않고 기존회사를 통해 간접적으로 소유하게 되면서 소액주주의 주식평가가치의 하락이 나타날 가능성이 있다.','','ㄱㅇㅂㅎ(ㅁㅈㅂㅎㅇㅈㅂㅎ)','{}'::text[]),
(138,'기업심리지수(CBSI)','기업심리지수(CBSI; Composite Business Sentiment Index)는 기업경기실사지수(BSI)의 주요 지수를 이용하여 산출한 지표이다.','기업심리지수(CBSI; Composite Business Sentiment Index)는 기업경기실사지수(BSI)의 주요 지수를 이용하여 산출한 지표이다. 제조업의 경우 업황, 생산, 신규수주, 제품재고, 자금사정의 BSI 수치를 합성하여 작성하며, 비제조업의 경우는 업황, 매출, 채산성, 자금사정의 BSI 수치를 합성하여 작성한다. CBSI는 100보다 클 경우 경제상황에 대한 기업들의 기대심리가 과거 평균보다 낙관적임을 나타내며, 반대로 100보다 작을 경우에는 기업회생절차비관적임을 의미한다.','','ㄱㅇㅅㄹㅈㅅ()',ARRAY['기업경기실사지수(BSI)']::text[]),
(139,'기업어음(CP)','기업어음(CP; Commercial Paper)은 신용상태가 양호한 기업이 상거래와 관계없이 운전자금 등 단기자금을 조달하기 위하여 자기신용을 바탕으로 발행하는 융통어음을 의미한다.','기업어음(CP; Commercial Paper)은 신용상태가 양호한 기업이 상거래와 관계없이 운전자금 등 단기자금을 조달하기 위하여 자기신용을 바탕으로 발행하는 융통어음을 의미한다. 따라서 상거래에 수반되어 발행되는 상업어음(commercial bill, 진성어음)과는 성격이 다르지만, 법적으로는 상업어음과 같은 약속어음으로 분류된다. CP는 발행절차가 간편하고 통상 담보없이 신용으로 발행되는 데다 대출대비 금리메리트도 있어 기업의 자금조달 수단으로 유용하게 활용되고 있다. CP 발행은 민간기업, 공기업, 증권사, 카드사, 특수목적회사(SPC) 등이 담당한다. CP의 할인 및 매출은 주로 증권회사가 담당한다. 한 편, 은행, 자산운용회사 및 보험회사 등의 CP 할인은 활발하지 않다. 은행의 경우 CP 할인이 대출로 간주되어 동일인 여신한도의 제한(자기자본의 20%)을 받는 데다 당좌대출, 상업어음할인 등 다양한 형태로 기업에 단기자금을 공급할 수 있기 때문이다. CP의 주요 매입주체는 자산운용회사의 MMF, 은행신탁, 증권신탁 등이다.','','ㄱㅇㅇㅇ()',ARRAY['진성어음/융통어음']::text[]),
(140,'기업회생절차','기업이 자력으로 회사를 꾸려가기 어려울 만큼 부채가 많을 때 법원에서 지정한 제3자가 자금을 비롯하여 기업활동 전반을 관리하는 것을 말한다.','기업이 자력으로 회사를 꾸려가기 어려울 만큼 부채가 많을 때 법원에서 지정한 제3자가 자금을 비롯하여 기업활동 전반을 관리하는 것을 말한다. 이는 재정적 어려움으로 파산에 직면하였으나 회생 가능성이 있는 기업의 경우에는 기업에 대한 채권자, 주주, 기타 이해관계인의 이해를 조정하여 정리재건을 도모하는 제도이다. 부도 위기에 몰린 기업을 파산시키는 것보다는 살리는 것이 기업과 채권자에게는 물론 국민경제 전반에 이롭다는 점이 이 제도의 취지이다. 기업이 회생절차를 신청할 경우 법원은 기업에 대한 채권, 채무이행을 동결시킨 다음 3개월 정도의 시간을 갖고 회생신청을 받아들일지, 기각할지를 결정한 다. 회생신청이 기각되면 기업은 파산절차에 들어가고, 수용되면 법원이 선임한 관리인이 기업의 경영을 책임지게 된다.','','ㄱㅇㅎㅅㅈㅊ','{}'::text[]),
(141,'기저효과','기저효과(Base Effect)는 경제지표 증가율을 해석할 때 기준시점과 비교시점의 상대적인위치에 따라서 경제 상황에 대한 평가가 실제보다 위축되거나 부풀려지는 등의 왜곡이 일어나는 것을 말한다.','기저효과(Base Effect)는 경제지표 증가율을 해석할 때 기준시점과 비교시점의 상대적인위치에 따라서 경제 상황에 대한 평가가 실제보다 위축되거나 부풀려지는 등의 왜곡이 일어나는 것을 말한다. 즉 호황기의 경제 상황을 기준시점으로 현재의 경제 상황을 비교할경우 경제지표는 실제보다 위축된 모습을 보이는 반면, 불황기의 경제 상황을 기준시점으로 비교하면 경제지표가 실제보다 부풀려져 나타날 수 있다. 기저효과는 물가상승률을 설명할 때도 자주 이용된다. 예를 들어 지난해 여름에 태풍 피해로 농산물가격이 급등하였다면, 전년동기대비로 계산한 올해 여름의 농산물가격 상승률은 상대적으로 낮게 나타날것이다. 반대로 지난해 가을 기상여건 호조에 따른 공급과잉으로 과일가격이 폭락하였다 면 올해 가을의 과일가격 상승률은 높은 수준을 보일 가능성이 크다. 따라서 경제지표를 보다 정확히 해석하기 위해서는 기준시점에 특수한 상황이 발생했는지 살펴보고, 그로 인해 비교시점의 지표가 어떤 영향을 받고 있는지 고려할 필요가 있다.','','ㄱㅈㅎㄱ',ARRAY['계절변동조정시계열']::text[]),
(142,'기준금리','한국은행 금융통화위원회에서 결정하는 정책금리를 말한다.','한국은행 금융통화위원회에서 결정하는 정책금리를 말한다. 한국은행과 금융기관 간에 환매조건부채권매매(RP)와 대기성 여수신 등의 자금거래를 할 때 기준으로 적용된다. 2008년 3월부터 한국은행은 정책금리의 실체를 종전의 ‘익일물 콜금리 목표’에서 ‘기준금리(Base Rate)’로 변경하였다. 콜금리는 대표적인 시장금리 중 하나로 초단기 금융시장의 자금상황을 반영하는 금리이다. 그러나 1999년 콜금리목표제를 도입한 이후 콜금리가 자금수급사정에 관계없이 목표수준에서 고정되면서 콜금리의 시장신호 전달 및 자금배분기능이 약화되었고, 단기자금거래가 콜시장에 과도하게 집중되어 금융기관 간 RP 등 기일물 단기자금시장의 발달이 저해되는 부작용이 발생하였다. 한국은행이 정책금리의 실체를 ‘기준금리’로 변경한 것은 이러한 문제를 해소하는 한편 통화정책 파급경로(정책금리 변경→단기 및 장기 시장금리 변동)의 원활한 작동을 도모하기 위한 것이다.','','ㄱㅈㄱㄹ',ARRAY['환매조건부매매/RP/Repo']::text[]),
(143,'기준순환일','기준순환일이란 경기변동 과정에서 국면전환이 이루어진 일자를 의미한다.','기준순환일이란 경기변동 과정에서 국면전환이 이루어진 일자를 의미한다. 즉 경기가 확 ㄱ 장국면에서 수축국면으로 전환하는 경기정점 또는 수축국면에서 확장국면으로 전환하는 경기저점의 구체적인 일자를 말한다. 경기변동은 이론적이고 추상적인 개념이기 때문에 현실적으로는 생산, 소비, 투자, 고용 등 경기변동 상황을 비교적 잘 반영하는 여러 지표를 통계적으로 가공한 후 그 움직임을 파악하여 판단한다. 그러나 이러한 경기변동의 실증적 연구는 분석 방법에 따라 결과가 다양하게 나오는 경우가 일반적이다. 이러한 점을 고려하여 각국의 통계 당국은 여러 측면을 살펴보고 하나의 기준순환일을 공식적으로 정하고 있다. 우리나라에서는 통계청이 기준순환일을 월 단위로 발표하고 있다. 기준순환일은 경기변동이라는 추상적 개념을 현실적인 경제의 움직임과 구체적으로 연결시켜주는 매우 중요한 고리의 역할을 한다. 기준순환일이란 용어가 언제부터 쓰이게 되었는지는 분명하지 않으나 문헌상으로는 1940~50년대 미국경제연구소(NBER; National Bureau of Economic Research)에서 발간한 경기변동관련 연구로부터 유래한 것으로 추정된다.','','ㄱㅈㅅㅎㅇ',ARRAY['경기','경기종합지수','동행종합지수']::text[]),
(144,'기준환율','기준환율이란 일반적으로 “다른 외국 통화 환율 결정의 기준이 되는 특정 통화의 환율” 을 의미한다.','기준환율이란 일반적으로 “다른 외국 통화 환율 결정의 기준이 되는 특정 통화의 환율” 을 의미한다. 우리나라의 경우 원/달러 환율이 기준환율이며 원/엔, 원/유로, 원/파운드등 여타 각국 통화의 환율은 원/달러 환율과 각국 통화의 대미달러화 환율을 기초로 하여 자동적으로 산출(재정환율)된다. 한편 기준환율은 외국환은행이 고객과 원화를 대가로 미 달러화를 매매할 때 기준이 되는 환율(매매기준율)을 의미하기도 한다. 매매기준율은 외국환중개회사를 통해 전 영업일 거래된 은행 간 원/달러 현물환거래 중 익일물(value spot)의 거래환율을 거래량으로 가중평균하여 결정되며, 현재 서울외국환중개회사가 원/ 달러 및 원/위안 기준환율과 55개 재정환율을 매일 아침 고시하고 있다. 한편 각 은행, 환전상 등이 고객에게 자국 통화와 외국 통화를 매입/매도하는 거래에서 적용하는 대고객환율은 기준환율에다 외환 환전 업무에 소요되는 리스크, 업무 처리 비용, 수익 등을 종합적으로 반영하여 자체적으로 정하게 되므로 기관마다 조금씩 다르게 된다.','','ㄱㅈㅎㅇ',ARRAY['재정환율']::text[]),
(145,'기초가격','기초가격(Basic Price)은 일정 기간 동안 경제주체가 생산한 생산물을 가격으로 평가함에 있어 생산자가격에서 부가가치세와 같은 생산물세(production tax)를 제외하고 정부에 서 주는…','기초가격(Basic Price)은 일정 기간 동안 경제주체가 생산한 생산물을 가격으로 평가함에 있어 생산자가격에서 부가가치세와 같은 생산물세(production tax)를 제외하고 정부에 서 주는 보조금(subsidy)을 더한 가격을 의미하는 것으로 순수하게 생산자(주로 기업)가 갖게 되는 몫을 말한다. 일반적으로 생산물을 최종 소비하는 소비자가 지불하는 가격 즉, 구매자가격에는 생산물세와 보조금, 운수비용, 거래마진 등이 모두 포함되어 있으며, 생산자가격은 기초가격에다 생산물세를 더하고 보조금을 차감한 가격을 말한다. 예를 들어정부가 국민 건강증진의 일환으로 축산농가를 지원하기 위해 우유 1병에 50원의 보조금을 주며 100원의 생산물세와 200원의 거래마진이 발생한다고 가정하자. 또한 이 우유가 상점에서 1,000원에 판매되고 있다고 하자. 이 경우 구매자가격은 소비자가 지불하는 가 격 1,000원이며, 생산자가격은 구매자가격 1,000원에서 유통업자의 몫인 거래마진 200 원을 뺀 800원이고, 기초가격은 생산자가격 800원에서 정부에 납부하는 세금 100원을 차감하고 정부로부터 받은 보조금 50원을 더한 750원이 된다. GDP를 추계할 때 생산물의 가격평가는 기초가격으로 하는 것을 원칙으로 하는데, 그 이유는 생산성 분석 등에 세금 등으로 인해 초래되는 분석결과의 왜곡을 피하기 위해서다.','','ㄱㅊㄱㄱ',ARRAY['국내총생산(GDP)']::text[]),
(146,'기축통화','기축통화란 여러 국가의 암묵적인 동의하에 국제거래에서 중심적인 역할을 하는 통화를 지칭한다.','기축통화란 여러 국가의 암묵적인 동의하에 국제거래에서 중심적인 역할을 하는 통화를 지칭한다. 구체적으로는 ① 국제무역결제에 사용되는 통화 ② 환율 평가 시의 지표가 되는 통화 ③ 대외준비자산으로 보유되는 통화 등의 의미를 포함한다. 그러므로 어떤 나라의 통화가 기축통화가 되기 위해서는 세계적으로 원활히 유통될 수 있도록 유동성이 풍부하여야 하고, 거래당사자들이 믿고 사용할 수 있도록 신뢰성을 갖추어야 하며, 국제적으로 경제력은 물론 정치력·군사력까지 인정받는 국가의 통화여야 한다. 20세기 초반까지는 세계 금융경제의 중심이었던 영국의 파운드화가 기축통화로서 국제거래에 주로 이 용되었으며, 2차 세계대전 이후에는 전 세계 외환거래 및 외환보유액의 상당 부분을 차지하는 미국 달러화가 기축통화로 인정받고 있다. 한편 현재 국제거래에서 비교적 자주기펜재사용되는 통화로는 미국 달러화 이외에도 유로화, 영국 파운드화, 일본 엔화, 스위스 프랑화 등이 있는데 이들을 흔히 교환성 통화라 한다.','','ㄱㅊㅌㅎ',ARRAY['교환성 통화']::text[]),
(147,'기타기본자본(Additional Tier 1)','기타기본자본(AT1; Additional Tier 1)은 바젤Ⅲ 자본규제에서 기본자본(Tier 1)을 구성하는 요소로서, 은행의 계속적인 영업을 전제로 손실흡수능력이 있다고 인정되는(혹은 은 행의…','기타기본자본(AT1; Additional Tier 1)은 바젤Ⅲ 자본규제에서 기본자본(Tier 1)을 구성하는 요소로서, 은행의 계속적인 영업을 전제로 손실흡수능력이 있다고 인정되는(혹은 은 행의 손실을 보통주자본 다음의 순서로 보전할 수 있는) 자본을 의미하며 영구적 성격을 지닌 자본증권의 발행으로 인한 자본금·자본잉여금 등이다. 기타기본자본증권으로 인정받기 위해서는 예금자, 일반 채권자 및 후순위채권보다 후순위일 것, 영구적일 것, 배당및 이자지급의 임의성, 중도상환 유인이 없을 것 등의 요건을 충족해야 한다(참고 「은행업감독업무시행세칙」별표 3).','','ㄱㅌㄱㅂㅈㅂ()',ARRAY['기본자본(Tier 1)','보통주자본(CET1)']::text[]),
(148,'기펜재','일반적으로 재화는 수요의 법칙에 따라 가격이 하락하면 수요량이 늘어난다.','일반적으로 재화는 수요의 법칙에 따라 가격이 하락하면 수요량이 늘어난다. 그러나 예외적으로 재화의 가격이 하락할 때 수요량이 감소하는 현상을 관찰할 수 있다. 이렇게 가 격이 하락할 경우 수요의 법칙에 위배되는 재화를 영국 경제학자 기펜(R. Giffen)의 이름을 따라 기펜재라고 부른다. 기펜재는 열등재의 일종이다. 소득이 증가함에 따라 수요가 감소하는 재화를 열등재라 하는데, 열등재 중에서도 열등성이 매우 커서 소득효과가 가격하락에 따른 수요량 증가의 대체효과를 초과하여, 결과적으로 가격이 하락할 때 수요량이 감소되는 것으로 분석할 수 있다. 가격이 상승할 경우에는 반대의 방향으로 설명할 수있다.','','ㄱㅍㅈ',ARRAY['밴드웨건효과','베블런효과']::text[]),
(149,'기회비용','인간의 욕구에 비해 자원이 부족한 현상을 희소성이라고 한다.','인간의 욕구에 비해 자원이 부족한 현상을 희소성이라고 한다. 희소한 자원을 가지고 인간의 모든 욕구를 충족시킬 수 없기 때문에 인간은 누구든지 부족한 자원을 어느 곳에 우선으로 활용할 것인가를 결정하는 선택을 해야 한다. 즉 다양한 욕구의 대상들 가운데서 하나를 고를 수밖에 없다. 이때 포기한 선택의 욕구들로부터 예상되는 유·무형의 이익 중최선의 이익을 기회비용(Opportunity Cost)이라고 한다. 자원의 희소성이 존재하는 한 기회비용은 반드시 발생하게 되고 이는 경제문제를 발생시키는 근본요인이 된다. 기업은 투자를 선택할 경우 포기한 나머지 선택의 가치인 투자금액의 은행예금 이자 등이 기회비용이 된다.','','ㄱㅎㅂㅇ',ARRAY['한계비용']::text[]),
(150,'기후테크','기후테크(Climate Tech)는 기후 변화 문제를 해결하거나 완화하기 위한 기술을 말한다.','기후테크(Climate Tech)는 기후 변화 문제를 해결하거나 완화하기 위한 기술을 말한다. 현재 태양광 및 풍력 등 청정에너지 개발, 탄소 포집 및 저장, 전기차 및 수소차 등 친환경이동수단, 데이터/AI 기반 기후 솔루션, 기후 리스크 분석 플랫폼 등 다양한 분야에서 기후테크 발전이 이뤄지고 있다. 기후테크는 폭염, 홍수, 가뭄 등 갈수록 심해지는 기후 위기를 완화하기 위한 필수적 수단인 데다 글로벌 환경규제 강화 추세에 대비한 신성장 산업으로도 부상하고 있다. 따라서 각국 정부와 기업은 기후테크에 대한 투자를 강화하여에너지 안보와 경제시스템 전환을 동시에 달성하고자 노력하고 있다.','','ㄱㅎㅌㅋ',ARRAY['에너지 믹스','녹색기후기금(GCF)']::text[]),
(151,'긴급수입제한조치','긴급수입제한조치(Safeguard) 즉, 세이프가드란 특정 품목의 수입이 급증하여 국내 업체에 심각한 피해가 발생하거나 그럴 우려가 있을 경우, 수입국이 관세 인상이나 수입량 제한 등을 통해…','긴급수입제한조치(Safeguard) 즉, 세이프가드란 특정 품목의 수입이 급증하여 국내 업체에 심각한 피해가 발생하거나 그럴 우려가 있을 경우, 수입국이 관세 인상이나 수입량 제한 등을 통해 수입품에 대한 규제를 할 수 있는 제도이며 무역장벽의 하나라고 볼 수 있다. 현재 세계무역기구(WTO; World Trade Organization)는 가입국들이 긴급수입제한 꼬리위험조치를 실행할 권리를 인정하고 있다. 수입물품에 대한 수량제한, 관세율 조정 및 국내산업의 구조조정을 촉진하기 위한 지원정책 등이 세이프가드로 동원될 수 있다. 그러나 세계무역기구의 세이프가드 협정은 제한적으로 취해져야 하고 세이프가드를 실시하는 수입 ㄱ 국은 해당 물품의 수출국에 적절한 보상을 해줄 것을 권고하고 있다.','','ㄱㄱㅅㅇㅈㅎㅈㅊ',ARRAY['상계관세','슈퍼301조']::text[]),
(152,'긴축정책','경기과열 우려가 있는 경우 재정 또는 통화정책으로 가계, 기업, 정부 등 각 경제주체들의 재화 및 서비스에 대한 수요, 투자 의지를 위축시켜 지출을 줄이는 등 경기의 과열을 방지하려는 정책을…','경기과열 우려가 있는 경우 재정 또는 통화정책으로 가계, 기업, 정부 등 각 경제주체들의 재화 및 서비스에 대한 수요, 투자 의지를 위축시켜 지출을 줄이는 등 경기의 과열을 방지하려는 정책을 긴축정책(Contractionary Policy)이라고 한다. 경기가 과열되어 물가급등 에 대한 염려가 커지면 정부나 지방자치단체는 예산을 편성·실행함에 있어서 지출을 삭감·억제함과 동시에 공채의 정리 및 신규 모집을 하지 않는 정책을 취한다. 세입 일부를 다음 연도로 이월하거나 공정이율의 인상을 중심으로 하는 금융긴축 조치 등도 시행된다. 한편 중앙은행은 물가급등에 대한 우려가 커지면 시중에 유통되는 통화량을 줄이거나 금리를 인상한다. 이렇게 되면 경제주체들의 지출이 줄어들면서 국민소득이 감소하고 지출축소와 소득 감소의 연쇄 과정이 발생하면서 물가도 하락하게 된다.','','ㄱㅊㅈㅊ',ARRAY['경기조절정책/경제안정화정책','재정정책','통화정책']::text[]),
(153,'꼬리위험','경제성장률이나 주가, 환율 등 시장가격변수 분포의 꼬리부분 이벤트가 발생할 위험을 꼬리위험(Tail Risk)이라고 한다.','경제성장률이나 주가, 환율 등 시장가격변수 분포의 꼬리부분 이벤트가 발생할 위험을 꼬리위험(Tail Risk)이라고 한다. 양극단 꼬리부분에 해당하는 이벤트는 발생 가능성은 매우낮지만 일단 발생하면 경제 전체에 지대한 영향을 줄 수 있는 위험이다.','','ㄲㄹㅇㅎ','{}'::text[]),
(154,'낙수효과','정부가 경제정책으로 대기업과 고소득층 또는 부유층의 소득과 부를 먼저 늘려주게 되면이들의 소비와 투자 증가를 통해 전체 경제활동이 활발해지면서 결국에는 중소기업과 저소득층도 혜택을 볼 수 있다는…','정부가 경제정책으로 대기업과 고소득층 또는 부유층의 소득과 부를 먼저 늘려주게 되면이들의 소비와 투자 증가를 통해 전체 경제활동이 활발해지면서 결국에는 중소기업과 저소득층도 혜택을 볼 수 있다는 주장이다. 이러한 주장은 분배와 형평성보다는 성장과 효율성을 중시하는 논리에 근거한다. 실제로 미국에서는 제41대 대통령인 부시가 1989년부터 1992년까지 낙수효과(Trickle-Down Effect)에 기반을 둔 경제정책을 채택하기도 했다. 그러나 1993년 1월 당선된 클린턴 행정부는 이를 뒷받침하는 근거가 없다는 이유를 들어 이전의 정책을 포기한 바 있다. 2015년 국제통화기금(IMF)은 선진국, 신흥국 및개발도상국을 대상으로 한 연구(“Causes and Consequences of Income Inequality: A Global Perspective”, IMF 2015년 6월)를 통해 상위소득 20% 계층의 비중이 커질수록경제성장률이 낮아진다는 실증분석 결과를 발표하였는데, 이는 낙수효과가 현실에서 작동하지 않을 수 있음을 시사한다.','','ㄴㅅㅎㄱ',ARRAY['분수효과']::text[]),
(155,'낙인효과','범죄학의 낙인이론에 따르면 일탈 또는 범죄 행동은 관련 주체의 독자적 행동에 의해서도 발생하지만, 해당 행동에 대한 사회적 평가 또는 해당 행동을 한 주체의 사회적 소외의 결과로도 발생할 수 있다.','범죄학의 낙인이론에 따르면 일탈 또는 범죄 행동은 관련 주체의 독자적 행동에 의해서도 발생하지만, 해당 행동에 대한 사회적 평가 또는 해당 행동을 한 주체의 사회적 소외의 결과로도 발생할 수 있다. 어떤 사람이 실수나 불가피한 상황에 의해 사회적으로 바람직하 ㄴ 지 못한 행위를 한 번 저지르고 이로 인해 나쁜 사람으로 낙인찍히면 그 사람에 대한 부정적 인식이 형성되고 이 인식은 쉽게 사라지지 않는다. 이로 인해 추후 어떤 상황이 발생했을 때 해당 사람에 대한 부정적 사회인식 때문에 유독 그 사람에게 상황이 부정적으로 전개되어 실제로 일탈 또는 범죄행위가 저질러지는 현상을 낳는데, 이를 낙인효과라고 한 다. 경제 분야에서도 이러한 현상이 발생한다. 예를 들어, 과거에 한 번 부도를 일으킨 기업이나 국가의 경우 이후 건전성을 회복했다 하더라도 시장의 충분한 신뢰를 얻기 어려워지며, 나아가 신용위기가 발생할 경우 투자자들이 다른 기업이나 국가보다 해당 기업이나 국가를 덜 신뢰하여 투자자금을 더 빨리 회수하고 이로 인해 실제로 해당 기업이나 국가 가 위기에 빠질 수 있다.','','ㄴㅇㅎㄱ','{}'::text[]),
(156,'난외거래','은행의 권리·의무가 확정되지 않아 재무상태표상(on-balance sheet) 자산·부채로 기록되지 않는 거래를 의미한다.','은행의 권리·의무가 확정되지 않아 재무상태표상(on-balance sheet) 자산·부채로 기록되지 않는 거래를 의미한다. 대표적인 난외(off-balance sheet)거래로는 신용 대체거래 (예: 채무보증), 특정 거래 관련 우발채무(예: 계약이행보증, 입찰보증, 환급보증 등), 무역금융(예: 신용장), 증권인수보증(NIF; Note Issuance Facility), 금리 및 외환 관련 파생상품거래의 신용리스크 상당액 등을 들 수 있다. 이러한 난외거래는 보증료 등을 통해 은 행의 수익성에 기여하고 효율적인 리스크 이전을 가능하게 해주는 등의 장점이 있지만 복잡한 거래구조 등으로 인하여 방만하게 취급될 경우 리스크 요인으로 작용할 수 있다. 따라서 감독당국은 최근 난외거래에 대한 감독을 강화하고 있으며 바젤은행감독위원회 (BCBS)도 자기자본비율 규제시 난외자산을 위험가중자산에 포함시켜 적절한 자기자본을 유지하도록 하고 있다.','','ㄴㅇㄱㄹ','{}'::text[]),
(157,'납부자자동이체','납부자자동이체(Standing Order)는 은행지로 업무의 한 형태로 고객이 거래은행이 아닌다른 은행에 대출원리금, 정기적금 등을 정기적으로 납부할 때 거래은행의 본인계좌에서 다른 은행으로 자동…','납부자자동이체(Standing Order)는 은행지로 업무의 한 형태로 고객이 거래은행이 아닌다른 은행에 대출원리금, 정기적금 등을 정기적으로 납부할 때 거래은행의 본인계좌에서 다른 은행으로 자동 이체시켜 주는 업무로서 1994년 4월부터 실시되었다. 납부자자동이 체는 주로 대출원리금, 적금 납입금, 신탁적립금, 기타 정기납부금(각종회비, 기부금, 임 차료) 등 정기적인 은행납입금 납부시 이용되고 있다.','','ㄴㅂㅈㅈㄷㅇㅊ',ARRAY['지로(GIRO)','출금이체']::text[]),
(158,'내국신용장','국내 외국환은행이 수출업자의 의뢰에 따라 수출업자 앞 국제 신용장(Master L/C)을 담보로 하는 등의 방식으로 국내 제조업자 또는 공급업자 앞으로 발행하는 신용장을 말한 다.','국내 외국환은행이 수출업자의 의뢰에 따라 수출업자 앞 국제 신용장(Master L/C)을 담보로 하는 등의 방식으로 국내 제조업자 또는 공급업자 앞으로 발행하는 신용장을 말한 다. 수출업자가 수출용 수입원자재와 국내에서 생산된 수출용 원자재 또는 수출용 완제품을 구매하는 경우에 외국환은행이 동 물품대금의 지급을 보증하는 지급보증서의 일종이 다. 국제간에 이용되는 신용장과 유사하나 내국신용장은 국내거래에만 사용 가능하며 거래 시 수출용임이 입증되어야 한다. 거래당사자로는 개설의뢰인(물품수요자), 수혜자(물품공급자), 개설은행 및 매입은행 등이 있다. 내국신용장에 의한 거래는 물품공급대금의 조기회수, 무역금융 융자수혜, 부가가치세 영세율(零稅率) 적용, 무역금융융자대상 수출실적 인정, 관세환급 등의 장점이 있다. 내국 신용장을 받은 물품공급자는 물품공급 후 판매대금추심의뢰서를 발행하고 관련 서류를 첨부하여 거래은행에 판매대금 추심을 의뢰함 으로써 일반 상업어음보다는 물품대금을 조기에 회수하게 된다.','','ㄴㄱㅅㅇㅈ','{}'::text[]),
(159,'내부등급법','바젤 자본규제에서 정하고 있는 최소 요건(신용평가 시스템의 신뢰도 확보를 위해 갖추어야 할 최소한의 양적·질적 요건)을 충족하여 감독당국의 승인을 받은 은행이 자산군별로 리스크 측정 요소(부도율…','바젤 자본규제에서 정하고 있는 최소 요건(신용평가 시스템의 신뢰도 확보를 위해 갖추어야 할 최소한의 양적·질적 요건)을 충족하여 감독당국의 승인을 받은 은행이 자산군별로 리스크 측정 요소(부도율, 부도시 손실률, 부도시 익스포저 등)를 자체 측정모형을 통해 추정하고 이를 바젤위원회(BCBS)가 정한 내부등급법 산식에 대입하여 신용리스크에 대한 위험가중자산을 산출하는 방법을 말한다. 내부등급법은 부도율에 대해서만 자체노동생산성/노동생산성지수추정을 허용하고 나머지 요소들은 감독당국이 정한 값을 사용하도록 하는 기본내부등급법과 모든 리스크 측정 요소의 자체 추정을 허용하는 고급내부등급법으로 구분된다. 내부등급법은 바젤Ⅱ부터 자본규제 체계의 리스크 민감도를 높이고 은행의 리스크 관리기법개선을 촉진할 목적으로 도입되었다. 그러나 리스크 측정모형과 관련된 불확실성으로 인해 위험가중자산이 잘못 산출될 가능성(모형 리스크)이 존재하는 데다 내부모형의 차이로 인해 은행간·국가간 위험가중자산의 편차가 과도하게 확대되어 자기자본비율 규제의 신뢰성을 저하시키는 요인이 되었다. 이에 따라 바젤Ⅲ에서는 객관적 리스크 측정이 어렵거나 자료가 부족하여 은행 자체 모형의 검증이 어려운 자산군에 대해서는 내부등급법 사용을 제한하는 등 위험가중자산의 편차를 축소하기 위한 조치를 취하였다.','','ㄴㅂㄷㄱㅂ','{}'::text[]),
(160,'내부자금','기업은 투자에 필요한 자금을 기업 내부 또는 기업 외부에서 조달하는데, 기업이 투자 재원을 내부유보, 감가상각충당금 등에서 조달한 것을 내부자금이라고 한다.','기업은 투자에 필요한 자금을 기업 내부 또는 기업 외부에서 조달하는데, 기업이 투자 재원을 내부유보, 감가상각충당금 등에서 조달한 것을 내부자금이라고 한다. 그리고 금융기관 차입, 유가증권 발행, 해외차입 등을 통해 조달한 것을 외부자금이라고 한다. 한편 내부유보란 기업의 손익거래의 결과로 나타난 잉여금 중 사외유출분을 제외하고 사내에 유보된 이익잉여금 등을 말하고, 감가상각충당금이란 기계와 같은 유형자산의 대체를 위해기업이익 중 일부를 비축하는 것을 말하는데 이것이 필요한 이유는 기계와 같은 유형자산은 생산과정에서 사용되고 시간이 흐르면서 노후화 되어 언젠가는 새로운 자산으로 대체되어야 하기 때문이다. 내부자금은 조달비용도 들지 않고, 이자나 배당을 지급할 필요도 없는 유리한 자금이다. 통상 고정투자가 활발하지 않을 경우 외부자금 수요가 줄어들면서 기업들의 내부자금 조달 비중이 상대적으로 높아지는 경향을 보인다.','','ㄴㅂㅈㄱ',ARRAY['외부자금']::text[]);
